import{It as e,vi as t,yi as n}from"./index-CO8wnKU1.js";var r={"Stormveil Village":`Stormbreaker`,"Ashen Leaf Village":`Root Liberator`,"Frostfang Village":`Oathbreaker`,"Moonshadow Village":`Moon Unmasked`};function i(e,t,n,r,i=n,a=`Player`){return{title:e,scene:t,speaker:n,dialogue:r,leftName:i,rightName:a,choices:[]}}function a(i,a,o,s,c,l,u=[]){let d=t[a]??t[4],f={bossName:s,bossIcon:c,bossHp:d.hp,bossDamage:d.damage,aiProfileId:n(i,a),xpReward:d.xp,ryoReward:d.ryo},p=l.map((e,t)=>t===l.length-1?{...e,choices:[...e.choices??[],...u.map(e=>({...e,nextPage:t,battle:f}))]}:e);return{levelReq:a,title:o,cinematicTitle:l[0]?.title??o,scene:l[0]?.scene??o,dialogue:l.flatMap(e=>e.dialogue),bossName:s,bossIcon:c,bossHp:d.hp,bossDamage:d.damage,rewardXp:d.xp,rewardRyo:d.ryo,biome:e[i]??`central`,aiProfileId:n(i,a),kageFinale:a===100,liberatorTitle:a===100?r[i]:void 0,pages:p}}var o={"Stormveil Village":[a(`Stormveil Village`,4,`First Thunder`,`Stormveil Training Scout`,`⚡`,[{...i(`The Challenge Board`,`The arena rim at dusk, chalk odds on slate, banner cables humming`,`Mira Volt`,[`You're new. Stand over here. The ground on that side is wet, and those cables are live.`,`I'm Mira. I take care of the rigging around the arena.`,`That's the challenge board. Someone posts a grievance, someone else answers it, and everybody comes to watch. Afterward, if nobody is badly hurt, there's soup.`,`The clerk will ask why you're fighting. Just tell him.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`},{...i(`The Reason Line`,`The board clerk's stand, a wet brush waiting`,`Ledger Clerk`,[`Your name first. Then tell me which bout you're answering.`,`Now I need a reason. I write down whatever you say.`,`You can take a minute if you need one.`,`Why are you fighting?`]),image:`/scenes/story/story-stormveil-village-4-0.webp`,choices:[{text:`"So nobody else has to."`,nextPage:2,trait:`sv4-post-protector`},{text:`"To be the strongest name on this board."`,nextPage:3,trait:`sv4-post-strongest`},{text:`"Someone owes me. I intend to collect."`,nextPage:4,trait:`sv4-post-debt`},{text:`"I'm looking for someone. Fighting turns heads."`,nextPage:5,trait:`sv4-post-searcher`},{text:`"I don't have a reason I can say."`,nextPage:6,trait:`sv4-post-unknown`}]},{...i(`A Shield Reason`,`The clerk's stand`,`Ledger Clerk`,[`So nobody else has to. All right.`,`You're posted, %name. Welcome to Stormveil.`,`Try to remember you said that when someone gives you an easier reason later.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`,choices:[{text:`Step back from the board.`,nextPage:7}]},{...i(`A Ladder Reason`,`The clerk's stand`,`Ledger Clerk`,[`The strongest name on the board. You're not the first to say it.`,`You're posted, %name. Welcome to Stormveil.`,`Good luck. You'll need some.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`,choices:[{text:`Step back from the board.`,nextPage:7}]},{...i(`A Debt Reason`,`The clerk's stand`,`Ledger Clerk`,[`Someone owes you. Fine. I don't need the rest.`,`You're posted, %name. Welcome to Stormveil.`,`If you change your mind, tell me before the bout, not during it.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`,choices:[{text:`Step back from the board.`,nextPage:7}]},{...i(`A Searching Reason`,`The clerk's stand`,`Ledger Clerk`,[`Looking for someone. I hope this gets their attention.`,`You're posted, %name. Welcome to Stormveil.`,`What you say to them is your business.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`,choices:[{text:`Step back from the board.`,nextPage:7}]},{...i(`A Blank Reason`,`The clerk's stand`,`Ledger Clerk`,[`You can't say. All right. I'll leave it blank.`,`The board allows that, even if the odds-runners don't like it.`,`You're posted, %name. Welcome to Stormveil.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`,choices:[{text:`Step back from the board.`,nextPage:7}]},{...i(`Posted Twice`,`The board, slates clacking in the wind`,`Mira Volt`,[`Done? Good. Soup's on the east rim and the good cart runs out by second bell, so let's move.`,`Hold on.`,`Your slate's up twice. Same name, same bout, two slates. The board doesn't do that.`,`And now it's not up at all. Clerk! Your board ate the new blood.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`},{...i(`Elder Vanta`,`The board, an old man reading slates like weather`,`Elder Vanta`,[`Leave the clerk alone. He didn't do it.`,`I'm Vanta. I've watched this board a long time. I've seen it lose a name twice before.`,`Both times, something bad followed. I don't know if that means anything yet.`,`Go take your bout. I'll look into this.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`,choices:[{text:`Walk to the arena floor.`,nextPage:9}]},{...i(`The First Bout`,`The arena floor, chalk dust, the crowd leaning in`,`Mira Volt`,[`Rules, fast. First yield or first fall. No edges on a first bout. The bell starts it and the bell ends it, and everything between the bells is yours.`,`That scout has taken a hundred first-timers apart, so the odds-runners have you long. Don't take it personally. Take it as room to surprise people.`,`One more thing, because nobody told me when I was new. The crowd will roar. The board will listen. Fight anyway.`,`Bell's up. Go.`]),image:`/scenes/story/story-stormveil-village-4-0.webp`}],[{text:`Go before the thunder lands. First move, no ceremony.`,conclusion:`You cross the chalk before the bell's echo dies, and the crowd loves you instantly and forever. The scout catches your first strike an inch from his jaw and grins. Somewhere above the rim, thunder answers the bell, one beat early.`,trait:`reckless`},{text:`Circle him. Watch the feet, not the hands.`,conclusion:`His hands lie twice before his feet tell you the truth: the weight sits back before every real strike. By the third exchange you know his rhythm better than he does. At the rail, Mira murmurs that nobody watches feet their first night.`,trait:`suspicious`},{text:`Tell the clerk to raise the purse first.`,conclusion:`The crowd howls with delight at the nerve of it, and the odds swing hard while the clerk chalks a fatter line. Win or lose, you just taught the whole rim your name. The board, notably, spells it right this time.`,trait:`ambitious`}]),a(`Stormveil Village`,15,`The Riot Bell`,`Tempest Guard Captain`,`⚡`,[{...i(`The Market Breaks`,`The market square mid-riot, stalls going over, the riot bell hammering`,`Mira Volt`,[`Stay on the wall side. Don't swing unless something swings at you.`,`This didn't spread from one fight. Everybody started at once.`,`That's Besh with the crate. He sells buttons. I've never seen him hit anybody.`,`Get him to look at you. Ask him what's wrong.`]),image:`/scenes/story/story-stormveil-village-15-1.webp`},{...i(`The Empty Why`,`A cornered stall, a button-seller with bleeding knuckles`,`Narrator`,[`You catch the button-seller's arm mid-throw and turn him. His eyes take a moment to find you, like a man surfacing from deep water.`,`You ask him why. He opens his mouth to tell you.`,`Nothing comes. He looks at his own bleeding knuckles, then at the crate in his hands, and his face goes from fury to a terrible, lost blankness, like a page with the line rubbed out.`,`'I had it,' he says. 'A minute ago I had it.'`]),image:`/scenes/story/story-stormveil-village-15-1.webp`},{...i(`The Kage in the Square`,`The square, a big man walking into the riot unarmed`,`Kage Raiko Veyr`,[`Enough. Put it down. All of you.`,`Besh, drop the crate. Mara, your daughter is by the well. Go check on her. If you can't remember why you're fighting, stop until you can.`,`Is anyone badly hurt? No? Good. Get some water over here.`,`You. The newcomer. You went in without a weapon and talked to him. I noticed.`]),image:`/scenes/story/story-stormveil-village-15-1.webp`},{...i(`After the Kage`,`The square's edge, Raiko moving crowd to crowd, beloved`,`Mira Volt`,[`That's Raiko Veyr. He knows everybody, and everybody trusts him. I do too. Most of the time.`,`Now look at this before the Guard takes it.`,`It's a riot order with today's date and the Kage's seal. The route around the market was drawn in advance.`,`Somebody planned this. I want to know why.`]),image:`/scenes/story/story-stormveil-village-15-1.webp`,choices:[{text:`The Guard closes the square.`,nextPage:4}]},{...i(`Booked Guilty`,`The square gates chained, the Tempest Guard forming a line`,`Tempest Guard Captain`,[`By order of the tower: the square is closed. Everyone inside is booked for riot. Names to the clerk, marks on the slate, fines by the door. No exceptions.`,`Yes, including the wounded. The wounded can bleed in a line like everyone else.`,`The button man goes in the wagon. He can't state his own business; that's public disorder twice over.`,`You have a problem with the process, new blood, you know where the board is. Post it.`]),image:`/scenes/story/story-stormveil-village-15-1.webp`},{...i(`The Captain's Line`,`The wagon, Besh looking small between two guards`,`Narrator`,[`The wounded man by the well can't walk. The wagon has room for one more, and the Captain is deciding whether it's the wounded man or the button-seller who can't remember his own anger.`,`Mira is already coiling a cable around her fist, which is how she argues.`,`The riot bell has stopped. The square is very quiet, the way the arena gets between the bell and the first blow.`]),image:`/scenes/story/story-stormveil-village-15-1.webp`}],[{text:`Stand over the wounded man. He is not walking, and he is not booked.`,conclusion:`You plant yourself between the stretcher and the line, and the square watches the Guard decide whether arresting the person who stopped three fights is worth the odds. The Captain blinks first. The wounded man keeps his name off the slate, and you go on somebody's list for it.`,trait:`merciful`},{text:`Challenge the Captain, by name, in the open square.`,conclusion:`The oldest law in Stormveil: a posted challenge outranks a booking. The crowd chalks it on the nearest wall before the clerk can even arrive. The Captain takes off his cloak, folds it, and says he was hoping somebody would do this, and the square becomes an arena, because here it always was one.`,trait:`reckless`},{text:`Hold up the tallied order. Ask, loudly, who counts riots before they happen.`,conclusion:`The square goes still. The Captain reads the route lines, the wax, the tally marks, and for one long moment he is not a wall, he is a man looking at his own orders and not liking their handwriting. 'Booking stands,' he says finally. But he folds the order into his own coat, not the clerk's box.`,trait:`suspicious`}]),a(`Stormveil Village`,25,`Orders Written in Lightning`,`Lightning-Sealed Informant`,`⚡`,[{...i(`The Lifted Scroll`,`Mira's rooftop, rain coming, a stolen scroll between you`,`Mira Volt`,[`I took it from a Guard clerk. He thinks he lost it during the riot.`,`The tower wax is real. The route was drawn a week early, and there are eleven marks down the side.`,`I don't know what the marks mean. I do know somebody had the market surrounded before the first punch.`,`My mother would have called that laundering. Make a mess, then hide what you took inside it.`]),image:`/scenes/story/story-stormveil-village-25-2.webp`},{...i(`The Name on the Board`,`The rooftop, wind pulling at an old slate Mira keeps wrapped in oilcloth`,`Mira Volt`,[`There's something else. I don't show this to many people.`,`Kesa Volt. My mother. Cable rigger, best on the coast. Dead six years. And her grudge is still posted on the board, still drawing odds, still scheduled twice a season against a man who is also dead.`,`The clerks call it an estate bout. I don't care what they call it. She's dead. He is too.`,`I asked the tower to remove it. They said the account was still active. I haven't asked again.`]),image:`/scenes/story/story-stormveil-village-25-2.webp`,choices:[{text:`Show her the Red Tally token from the border. Same tick marks.`,nextPage:2,requireTrait:`rd22-showed-the-token`},{text:`"Take the scroll to Vanta. He reads boards better than anyone."`,nextPage:3}]},{...i(`The Same Hand`,`The rooftop, the lead token flat on the scroll`,`Mira Volt`,[`Where did you get that? Tell me on the way. We're going to Vanta.`,`Same tick marks. Same line under the count. Your border fire and my market riot, added up by the same hand.`,`This isn't only happening here.`,`Bring the scroll. Step where I step. Some of these roofs are rotten.`]),image:`/scenes/story/story-stormveil-village-25-2.webp`,choices:[{text:`Cross the roofs to Vanta.`,nextPage:3}]},{...i(`Vanta Reads the Wax`,`Vanta's rail-side shack, purse ledgers stacked to the ceiling`,`Elder Vanta`,[`Close the door. The rain's getting in.`,`The wax is real. So is the order. Somebody arranged the riot, then took something from the people in it. I've suspected that for years. I never had proof.`,`The eleven marks are an intake count. I think they took eleven reasons. I can remember every purse I've paid, but ask any fighter why they were angry the next morning and most of them can't tell you.`,`There's a shaft under the arena. Kesa knew about it. She tried to tell me, and I laughed at her.`]),image:`/scenes/story/story-stormveil-village-25-2.webp`,choices:[{text:`Someone is on the roof.`,nextPage:4}]},{...i(`The Listener`,`The shack, rain starting, a shape on the skylight`,`Narrator`,[`The skylight creaks. Not wind. Weight.`,`Vanta doesn't look up. He slides the scroll under a purse ledger with a bookmaker's smoothness and says, louder than he needs to, that the rain is early this year.`,`Through the glass, backlit by the first lightning, you can see the listener's hands moving. Tick, tick, tick. Counting the room.`,`'That one is sealed to the tower,' Vanta says quietly. 'Lightning-sealed. You can't out-talk it. Decide what it takes back with it.'`]),image:`/scenes/story/story-stormveil-village-25-2.webp`},{...i(`Sealed and Sent`,`The rooftops in the rain, the informant between you and the tower`,`Mira Volt`,[`It has the scroll's scent, or whatever sealed things have instead of a mind. It will carry what it saw straight up the hill.`,`We have one roof between it and the tower, and rain in our favor. Nobody watches feet in the rain; you taught me that.`,`Whatever you do, do it before the next lightning. It counts by the flashes. I watched it do it.`,`Go.`]),image:`/scenes/story/story-stormveil-village-25-2.webp`}],[{text:`Take the back stair tonight. Whatever's in the shaft, see it alone.`,conclusion:`You drop off the roof mid-fight and take the maintenance stair three at a time, alone, into the dark under the arena. Behind you the informant screams a sound like torn wire. Ahead, far down, something enormous turns over in its sleep, and the walls hum with stored weather.`,trait:`reckless`},{text:`Put the scroll in Vanta's hands and stand between him and the seal.`,conclusion:`Vanta folds the scroll into his ledgers, where one more page among ten thousand becomes invisible, and you plant yourself on the wet slate between the old man and the thing with counting hands. 'You're insane,' Mira says, taking your flank. 'Good. Stay that way.'`,trait:`honorable`},{text:`Copy the tally. Burn the rest, and let it watch you do it.`,conclusion:`You chalk the eleven marks onto your own slate while the original curls to ash in the rain barrel, and the sealed thing watches its errand become pointless in real time. Now the count exists in exactly one place, and the tower will have to come to YOU to read it.`,trait:`suspicious`}]),a(`Stormveil Village`,35,`The Storm Engine`,`Storm Engine Warden`,`⚡`,[{...i(`Down the Well That Isn't`,`The maintenance shaft under the arena, rungs slick, a hum below`,`Mira Volt`,[`Loose rung at the third landing. Vanta, are you still with us? Say something.`,`That vibration is coming from below. I've felt it in the roof cables for years. I thought it was the wind.`,`I was wrong.`,`Keep the lamps low. Don't touch anything until we know what it is.`]),image:`/scenes/story/story-stormveil-village-35-3.webp`},{...i(`Eleven Pipes`,`The engine floor: eleven great pipes running from the arena floor overhead into a banked crystal reserve`,`Narrator`,[`The arena is directly overhead. You can hear tonight's crowd through the stone, a heartbeat of stamping feet.`,`Eleven pipes come down from the fight floor like cables off a mast. Each one glows faintly with what it is carrying. The carrying does not stop.`,`Along the wall hang maintenance rotas, a mop, a kettle. Somebody works here on a schedule. Somebody has ALWAYS worked here on a schedule; the rota nail-holes climb the wall like tide marks.`,`In the middle of it all sits the reserve, banked like a hearth, and it is the size of a house, and it is nearly full.`]),image:`/scenes/story/story-stormveil-village-35-3.webp`},{...i(`The First Storm`,`An alcove off the engine floor, founders' slates behind wax`,`Elder Vanta`,[`Before you decide what this place is, read one of these.`,`This says, 'My feud with Harn's line, thirty years and both our fathers. Given to the sky, gladly, so my sons fight nothing but weather.' He signed it. Someone witnessed it.`,`That was the original bargain. People chose to give up a feud, and the engine used it to protect the village.`,`The pipes don't ask. The board keeps a grudge open until there is nothing left to take. At some point, we stopped asking permission.`]),image:`/scenes/story/story-stormveil-village-35-3.webp`,choices:[{text:`Ask Mira what her mother knew about this place.`,nextPage:3,requireTrait:`mira-trust`},{text:`Read the chalked figures at the pipe junctions.`,nextPage:4}]},{...i(`Kesa's Whisper`,`The alcove, Mira's lamp low`,`Mira Volt`,[`I never told you everything about my mother.`,`She came down here. I'm sure of it. After my father drowned, she started drawing anchors on the high ridge. Nobody understood what she was trying to build.`,`She posted her grievance, and after that they scheduled her every season. She got quieter each time. I thought she was getting better.`,`They were taking it from her.`,`Then she died, and they left her name on the board.`]),image:`/scenes/story/story-stormveil-village-35-3.webp`,choices:[{text:`Something moves by the reserve.`,nextPage:4}]},{...i(`The Warden of the Reserve`,`The engine floor, a founders' construct unfolding from the pipework`,`Narrator`,[`It stands up out of the pipework the way a rigger stands up out of a hammock: unhurried, at home, enormous.`,`The Storm Engine Warden. Founders' work, same hand as the alcove. It has stood this floor for four hundred years, and its post was never to keep people out.`,`Its post was to check what comes IN. It holds a slate, and on the slate is one question, worn nearly smooth by centuries of asking: STATE YOUR REASON.`,`It looks at each of you in turn. Vanta states forty years of guilt, plainly, and it lets him stand. Mira states her mother's name, and it bows its head an inch. Then it looks at you, and waits, and whatever it reads where your reason should be, it does not find, and its stance changes to the one on the older, sterner slates.`]),image:`/scenes/story/story-stormveil-village-35-3.webp`},{...i(`State Your Reason`,`The engine floor, the Warden between you and the reserve`,`Elder Vanta`,[`It isn't angry. It's following old instructions.`,`It can't read you, and it doesn't know what to do with that.`,`Raiko probably knows we're here. Whatever you decide, decide now.`,`Here it comes.`]),image:`/scenes/story/story-stormveil-village-35-3.webp`}],[{text:`Say it stops. To the Warden's face, on the record.`,conclusion:`You state a reason after all: this stops. The Warden's slate crackles as four centuries of filings rearrange around a sentence it has no column for. For a moment its stance is almost gratitude. Then it attacks, because a construct with a broken ledger has only one instruction left, and upstairs the crowd stamps, feeding the pipes.`,trait:`honorable`},{text:`Go for the reserve's bank, now, while it's mid-question.`,conclusion:`Mira yells your name and misses your collar by a finger. You go over the pipework at the banked crystal with your hands bare, and the whole floor howls awake at once. Whatever happens next, the engine will remember tonight the way a body remembers a burn.`,trait:`reckless`},{text:`Read the chalked figures at the junctions first. All of them.`,conclusion:`Draw rates, junction by junction, in a maintenance hand: the intake has doubled every decade and the outflow to the storm shield has not risen in forty years. The surplus is going somewhere with no chalk line to it. You memorize the whole count while the Warden closes, and Vanta whispers that you read figures like a man he used to be afraid of.`,trait:`suspicious`}]),a(`Stormveil Village`,50,`Jonin of the Unchained Sky`,`Jonin Rank Trial: Twin Tempest Duelists`,`⚡`,[{...i(`The Rite of the Posted Rival`,`The arena at noon, banners up, the board scrubbed clean for the rite`,`Ledger Clerk`,[`Stand on the chalk, face the board. This is the part of the rite everyone's family comes to see, so smile, or at least stop looking like weather.`,`Jonin of Stormveil post a lifetime rival. One name, on the board, forever. The village watches your whole career against one other name; it's how we make ambition public and keep it honest. That's the speech, anyway.`,`The board never forgets a posted name. Whatever else you hear today, that part is true.`,`The Kage is here. He posts the rite bouts himself. Try not to say anything I'll have to chalk.`]),image:`/scenes/story/story-stormveil-village-50-4.webp`},{...i(`Raiko's Dare`,`The rite chalk, Raiko grinning like the whole village's uncle`,`Kage Raiko Veyr`,[`There's my riot-stopper. Level with me, before the formal part: how's the shoulder? The Twins hit like falling scaffolding, and I'd rather promote you unbroken.`,`Now. The rival line. Most people post a training mate, someone safe. A rivalry you can have soup with after. Nothing wrong with that.`,`But you've been under my arena, so let's be adults. You want to post a name that means something? Post mine. Raiko Veyr, right there on the slate. I'll even hold the brush.`,`Careful, though. A posted grudge is a lifetime account here. Ask yourself who profits from holding yours open, and then ask why I'm smiling.`]),image:`/scenes/story/story-stormveil-village-50-4.webp`,choices:[{text:`Show him the junction figures. Ask where the surplus goes.`,nextPage:2,requireTrait:`sv42-kept-the-count`},{text:`Answer the dare at the board.`,nextPage:3}]},{...i(`The Missing Chalk Line`,`The rite chalk, the crowd noise far away for a moment`,`Kage Raiko Veyr`,[`You copied the numbers. You weren't supposed to see those.`,`I'm not going to lie to you. The surplus goes up the hill. There's an old debt tied to this seat, and every Kage inherits the payment schedule.`,`I keep the withdrawals small. Nobody has died in a grudge fight in thirty years, and the storm shield still works. I know what that has cost people. I made the choice anyway.`,`You want to know what I get from the seat? I hear every voice in that crowd, all the time. Now finish the rite.`]),image:`/scenes/story/story-stormveil-village-50-4.webp`,choices:[{text:`Walk back to the board.`,nextPage:3}]},{...i(`Supply Lines`,`The board's shadow, Mira pretending to check a cable anchor`,`Mira Volt`,[`Don't write his name. Please.`,`I know why you want to. You want the real fight where everyone can see it. But the board will keep scheduling it for the rest of your life.`,`My mother told the truth once. They used it for six years.`,`Leave the slate empty if you have to. People will call you a coward. You'll live.`]),image:`/scenes/story/story-stormveil-village-50-4.webp`,choices:[{text:`Take the brush.`,nextPage:4}]},{...i(`The Twin Tempest`,`The rite floor, two duelists uncoiling like paired lightning`,`Narrator`,[`Rank in Stormveil is not given. It is posted, and then it is tested, and the test is the Twin Tempest Duelists, who have fought as one organism since before you could walk.`,`The crowd settles into the particular hush it saves for rite bouts, the one that sounds like the whole village holding one breath.`,`At the rail, Raiko holds the brush he offered you, still smiling, watching what you do with your slate more closely than he will watch the fight.`,`The bell is up.`]),image:`/scenes/story/story-stormveil-village-50-4.webp`}],[{text:`Take the trial with an empty rival line. Refuse to post at all.`,conclusion:`You leave the slate blank in front of the whole village, and the silence has teeth. An unposted Jonin: no account to milk, no line to schedule. The clerk's brush hovers a long time. Raiko's smile goes somewhere private, and the board, which never forgets, has nothing of yours to remember.`,trait:`honorable`},{text:`Write Raiko's name on the board.`,conclusion:`The crowd's roar knocks birds off the tower. RAIKO VEYR, chalked as a lifetime rivalry by the newest Jonin in a generation. The Kage laughs like thunder finding a bell tower, and somewhere under the arena, eleven pipes lean toward the biggest account the board has ever opened.`,trait:`reckless`},{text:`Post a rival who died years ago. Watch what the board does.`,conclusion:`You post a dead name and watch the board accept it without a flicker: schedules, odds, a first bout three weeks out. It never checks the register of the living, because it was never about the living. Mira goes pale at the rail. Now you both know exactly how her mother is still fighting.`,trait:`suspicious`}]),a(`Stormveil Village`,65,`The Mission That Should Not Exist`,`Tempest Execution Squad`,`⚡`,[{...i(`The Ravine Order`,`The tower gatehouse, an order with fresh wax and no clerk's initials`,`Tempest Guard Captain`,[`Jonin. I have an order from the tower, and I don't like it.`,`There's a camp in the north ravine. About forty people. They're charged with sedition because they refuse to post their grievances on the board.`,`An execution squad left an hour ago. You're listed as the ranking witness.`,`I tried to write a protest this morning. I didn't send it. I'm sorry. If you ride now, you can reach the camp first.`]),image:`/scenes/story/story-stormveil-village-65-5.webp`,choices:[{text:`Ask what the order's pay line says. You know the shares now.`,nextPage:1,requireTrait:`sv58-refused-the-ninth`},{text:`Go north ahead of the squad.`,nextPage:2}]},{...i(`The Ninth Share`,`The gatehouse, the order flat between you`,`Tempest Guard Captain`,[`The pay line? All right. Look.`,`There are nine shares. Eight go to the squad. The ninth is marked like the elders' cut, with a quartered circle beside it.`,`That share was set aside for you before you accepted the order.`,`You can beat them there by half a bell. Use it.`]),image:`/scenes/story/story-stormveil-village-65-5.webp`,choices:[{text:`Ride north.`,nextPage:2}]},{...i(`The Camp That Keeps Its Anger`,`The ravine camp: cook fires, mended tents, slates nailed to posts with reasons written LARGE`,`Rebel Medic`,[`Stop there. I can see the village crest. Why are you here?`,`Yes, we refuse to post. My sister was arrested in a riot four years ago. She came home and couldn't remember why she'd left her husband.`,`So we argue in private. We lose sleep. Sometimes we stay angry for years. At least the anger is ours.`,`Once a season we intercept a cart of confiscated slates headed for the shaft. We keep them here because most of the owners no longer remember what was taken.`]),image:`/scenes/story/story-stormveil-village-65-5.webp`},{...i(`The Rescued Slates`,`A dry cave wall racked with hundreds of confiscated reason-slates`,`Mira Volt`,[`You ride too fast. I almost lost my horse trying to catch you.`,`Look at these. Weddings, land disputes, family fights. This one belonged to a child. Nine years old.`,`Wait.`,`This is my mother's handwriting. It's her grievance. And these are the ridge plans. I thought they were gone.`]),image:`/scenes/story/story-stormveil-village-65-5.webp`,choices:[{text:`Wrap Kesa's grievance and maps. They leave this ravine with you.`,nextPage:4,trait:`sv65-saved-the-reason`},{text:`Put the pages in Mira's hands. Her mother, her carrying.`,nextPage:4,trait:`sv65-gave-mira-the-page`},{text:`Reseal the rack. The camp keeps its dead honestly; leave them whole.`,nextPage:4,trait:`sv65-resealed-the-cart`}]},{...i(`Eight Riders`,`The ravine mouth, dust rising on the valley road`,`Rebel Medic`,[`Eight riders on the road. Tower gray.`,`There are children and old people here. Four of us can fight, and one of those four has a broken wrist.`,`You reached us first. That has to mean something.`,`Are you helping us or not?`]),image:`/scenes/story/story-stormveil-village-65-5.webp`},{...i(`The Ranking Witness`,`The ravine mouth, the squad dismounting with ceremony`,`Narrator`,[`The squad forms up with the unhurried confidence of people who have done this before and been thanked for it. Their leader carries the order like a shield.`,`Behind you, the camp bangs pots and herds children toward the caves, and a nine-year-old's rescued slate swings on the rack in the wind.`,`The order names you ranking witness. That means the squad, the camp, and every child behind you are waiting on your word.`,`The medic was right. Say it fast.`]),image:`/scenes/story/story-stormveil-village-65-5.webp`}],[{text:`Get between the squad and the tents. The order dies here.`,conclusion:`You put your back to the cook fires and your rank in the squad's road, and the arithmetic changes: eight shares are not worth a Jonin's posted testimony. They withdraw with ceremony, and the camp watches you the way people watch weather break. The tower will hear by morning, and the ninth share will find another line to sit on.`,trait:`merciful`},{text:`Take the camp's surrender. Loudly. On your record, on your terms.`,conclusion:`You arrest forty people in a voice that carries down the ravine, into YOUR custody, under YOUR seal, pending YOUR report, and the squad can only watch the whole prize walk away from them. It's a long game and everyone in the camp knows it, and the medic spits at your boots and then, quietly, thanks you.`,trait:`honorable`},{text:`Signal compliance. Then walk the squad into the wrong ravine.`,conclusion:`You confirm the order, note the camp's 'position,' and lead eight paid men up a fork that dead-ends in scree and evening. By the time they unknot the map, the camp is smoke and cold fires and gone. Lying to armed men in the dark: your hands don't shake until after, which frightens you more than the shaking would.`,trait:`suspicious`}]),a(`Stormveil Village`,75,`Kesa's Bout`,`Mira Volt, False Betrayer`,`⚡`,[{...i(`The Estate Closure`,`The board at dawn, a new slate in the estate column, Mira staring at it`,`Mira Volt`,[`They posted this this morning.`,`It's a closure bout for my mother's account. Because I'm her daughter, I have to fight it.`,`They matched me with you. Three days from now, main card.`,`I was going to leave. I'm not leaving. I have a plan, and I need you to listen before you tell me it's a bad one.`]),image:`/scenes/story/story-stormveil-village-75-6.webp`,choices:[{text:`"You read the routing mark on my fixed bout. Read this one."`,nextPage:1,requireTrait:`sv70-read-the-mark`},{text:`Hear the plan on the roof.`,nextPage:2}]},{...i(`The Routing Mark`,`The board, Mira's finger under the slate's corner`,`Mira Volt`,[`Look in the corner. It's the same routing mark that was on your bout. I learned how to read it.`,`They already filed the result. I'm supposed to lose in the fourth exchange, and the account closes at maximum draw.`,`They picked the moment I'm supposed to break down.`,`Meet me on the roof. Please.`]),image:`/scenes/story/story-stormveil-village-75-6.webp`,choices:[{text:`Up the cable run.`,nextPage:2}]},{...i(`Storm Rules`,`Mira's rooftop, the plan chalked on slate, her hands steady`,`Mira Volt`,[`Don't repeat this to anyone.`,`We can't stop the bout. But founders' law says a closure ends if the account holder's reason is spoken and settled. The rule is still on the oldest slate.`,`I've read my mother's reason enough times to know it by heart.`,`We fight for real. In the fourth exchange, I stop and read it. You keep the officials away from me until I'm done. If the rule still means anything, her account closes and her reason stays with me. Are you in?`]),image:`/scenes/story/story-stormveil-village-75-6.webp`,choices:[{text:`Three days pass. The bell.`,nextPage:3}]},{...i(`Main Card`,`The arena floor, the estate slate hung over the bell, the crowd enormous`,`Narrator`,[`They hang the estate slate above the bell where everyone can read it: KESA VOLT, CLOSURE. The odds say you beat Mira. They say her grief beats you both.`,`Mira stands across the chalk from you, wearing her mother's rigging gloves, and under the crowd noise she mouths the plan's last line: fight me true, and when I raise my hand, hold the ring. Don't let them stop me when I speak.`,`Under the sand, faint as a held breath, the seams begin to glow before the first exchange. The board does not care whether tonight's grief is honest; honest grief has always been its best draw. It has waited six years for this vintage.`,`The bell is up, friend.`]),image:`/scenes/story/story-stormveil-village-75-6.webp`}],[{text:`Fight her true, and guard the moment she stops to speak.`,conclusion:`You give her a real bout, hard and honest, and the seams light anyway: the last ugly proof that the floor never cared whether the fight was real, only whether the reason under it was still there to take. At the fourth exchange Mira raises her hand. You put your back to hers while the routing clerks shout that the account hasn't closed, and Kesa Volt's reason rings across the arena in her daughter's voice, named under founders' closure law, word for word, settled. The seams pull once, then let go. The estate account closes empty. The board hisses like rain on a forge, because the reason stayed with the person who carried it.`,trait:`loyal`},{text:`Tear the estate slate off the board mid-bout, in front of everyone.`,conclusion:`You break from the exchange, run the rail, and rip KESA VOLT off the board with both hands while the crowd loses its mind. Founders' law says a torn posting voids the bout; tower law says you just assaulted the board itself. Both are true. Mira stands in the chalk, gloves up, laughing and crying at the ruin of every script in the building.`,trait:`reckless`},{text:`Buy the account. Purse, odds, and the estate's debt, in your name.`,conclusion:`You halt the bout on a rule older than the tower: any account may be bought at closure by an open hand. Yours is the only hand rich enough, after the seasons you've had. Kesa Volt's account, her draw, her schedule, all of it now answers to you. You did not free her reason; you bought the right to hold it. Mira stares at you across the chalk, trying to decide what she just watched you become. The board files the transfer without complaint. It likes you.`,trait:`ambitious`}]),a(`Stormveil Village`,85,`The Kage's True Storm`,`Hollow Tempest General`,`⚡`,[{...i(`Fees Waived`,`The square under a bruise-green sky, clerks posting free bouts as fast as chalk allows`,`Tempest Guard Captain`,[`The tower waived every posting fee at dawn. The line reaches around the square, and the clerks are running out of slate.`,`I've watched this sky for thirty years. I've never seen it turn like that.`,`Raiko knows the bouts feed the engine. If he wants this many at once, the tower is trying to pay something tonight.`,`I sent a report saying the order was wrong. I should have done that years ago.`]),image:`/scenes/story/story-stormveil-village-85-7.webp`},{...i(`The Balloon Payment`,`The rail, Harrow with a valise and no intention of staying`,`Kite Harrow`,[`I was looking for you. I'm leaving tonight, so listen.`,`Your engine is one of four feeding the same reserve. Fire, frost, moon, and storm. I saw the payment order. The entire reserve comes due tonight.`,`Raiko is filling it with every grievance he can get. It still won't be enough. The debt was designed that way.`,`The surge valve is in the square, under that armored thing. Cut the square off from the engine and you can interrupt the payment.`]),image:`/scenes/story/story-stormveil-village-85-7.webp`,choices:[{text:`"Stay. Hold the coast gate open tonight. I'll owe you."`,nextPage:2,requireTrait:`sv80-pulled-her-back`},{text:`Head for the square.`,nextPage:3}]},{...i(`The Anomaly, Again`,`The rail, Harrow looking at her own valise like it betrayed her`,`Kite Harrow`,[`Stay? In that weather? For a favor?`,`You helped me once and asked for nothing. Fine. The coast gate stays open, and anyone who wants out gets out.`,`After this, we're even.`,`Go. I'll keep the door open.`]),image:`/scenes/story/story-stormveil-village-85-7.webp`,choices:[{text:`Head for the square.`,nextPage:3}]},{...i(`The Rigger's Answer`,`A rooftop over the square, cables everywhere, Mira already working`,`Mira Volt`,[`Don't talk, hold this. Turnbuckle. Other hand. Good.`,`I'm not leaving. My mother drew those ridge anchors for a storm like this. I'm going to finish the work.`,`The General is standing over the surge valve. Get it away from there. I'll handle the cables.`,`And, hey. Thank you. For my mother. Now go.`]),image:`/scenes/story/story-stormveil-village-85-7.webp`,choices:[{text:`The tower door stands open.`,nextPage:4}]},{...i(`The Weather Ledger`,`Raiko's office, storm maps and a lifetime of bout slates, the Kage watching his sky`,`Kage Raiko Veyr`,[`Come in. You were always coming here tonight; the only question was how angry. Sit. You'll argue better sitting; my knees argue better standing, so we're even.`,`Before you say it, two numbers. The Split-Sky year killed sixty of us. Roofs, floods, a lightning fire that took the low market in an hour. My first year in the seat I broke that storm's back with the reserve, and no one has died of weather in this village since. Not one. Thirty years, Jonin. That's my line on the board, and it's honest.`,`Tonight the debt above me calls its loan, and the whole reserve goes up the hill, and I refill it or the shield dies with the payment. So yes, I waived the fees. I'd waive worse than fees to keep this village under a roof.`,`Argue with me. I mean it. Everyone else just bets. Bring me a quieter storm, and the board rests tonight. That's not rhetoric. It's the one hole in my odds: show me this village standing through weather without feeding the floor, and I will close every intake myself, with a hammer.`]),image:`/scenes/story/story-stormveil-village-85-7.webp`,choices:[{text:`The square. The General.`,nextPage:5}]},{...i(`The Surge Valve`,`The square, the Hollow Tempest General planted like a monument, sky turning`,`Narrator`,[`The Hollow Tempest General does not patrol. It stands where the pipes meet, hands folded on its warhammer, and the ground under it breathes light in slow pulls: the payment, gathering.`,`Around the square's rim the whole village is posting, queuing, betting, feeding, under a sky that has begun, very gently, to rotate.`,`The Captain arrives with thirty guards and no orders. Mira's cables sing overhead. Somewhere up the hill, an account four villages wide waits to be paid in everyone's reasons.`,`The General's visor turns to you. The valve, its stance says, is spoken for. Speak otherwise.`]),image:`/scenes/story/story-stormveil-village-85-7.webp`}],[{text:`Rally every rim of the square to one banner before you swing.`,conclusion:`You do the impossible thing: you get the odds-runners and the Guard and the queue and the camp's riders under one shout, and the square stops feeding the floor because the whole square is watching you instead. The pipes gurgle on nothing. The General unfolds its hammer with what might be relief; a monument likes an honest fight.`,trait:`loyal`},{text:`Walk into the square alone and take the General now.`,conclusion:`No speech. You walk the open chalk with the whole village watching and hit the monument where it stands. The crowd's roar drowns the storm bell, the odds-runners tear up their slates, and the payment stutters as its valve is forced to defend itself. Somewhere above, the sky forgets its rotation for one full breath.`,trait:`reckless`},{text:`Shear the junction cables feeding the square first.`,conclusion:`Mira's maps in your head, you take the junctions in order, fast, while the queues still think you're a maintenance run. By the time the General understands the valve under it has gone quiet, the square is off the grid and the payment is coming up short exactly as an appraiser predicted. Uphill, something enormous notices the arithmetic.`,trait:`suspicious`}]),a(`Stormveil Village`,100,`Break the False Thunder`,`Kage Raiko Veyr, Hollow Storm Tyrant`,`⚡`,[{...i(`The Village Climbs`,`The tower road at dusk, the whole village walking up to watch`,`Narrator`,[`Word went out at noon bell, no one knows from whom: the last bout is tonight, at the top, and everyone is invited.`,`So Stormveil climbs. Soup carts and grandmothers, odds-runners with nothing chalked, the Captain in his best coat, the camp come down from the ravine carrying their slates like lanterns.`,`At the tower gate, for the first time in anyone's memory, the betting window is shuttered. A hand-lettered sign says: NO ODDS POSTED ON THIS ONE.`,`The board at the base of the tower is blank, and it is humming, and on the top step sits a bowl of soup going cold, with a note under it in a big cheerful hand: 'You'll fight better fed. R.'`]),image:`/scenes/story/story-stormveil-village-100-8.webp`},{...i(`At the Gate`,`The tower gate, Mira with her mother's gloves tucked in her belt`,`Mira Volt`,[`I know. Past the gate, it's only you and him. I'll stay here.`,`I checked the exits. Both are clear if this goes badly. The boat is still there too, but I'm not taking it.`,`If the sky comes apart, I can hold the ridge line. Go deal with Raiko.`,`Come over for soup afterward. I'm serious.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`Climb to the storm floor.`,nextPage:2}]},{...i(`The Drain Speaks`,`The storm floor, open to the rotating sky, Raiko at the rail`,`Kage Raiko Veyr`,[`You're on time.`,`Before we fight, I'll answer one question. The debt above this village is called the Hollow Gate. There are four seats tied to it, one for each village. I don't know what the others were promised. I know what I was promised.`,`Quiet. One hour a day when I don't hear every grievance in Stormveil. It sounds small. It isn't. I have done terrible things to keep that hour.`,`Kesa Volt's grief fed the shield for six years. I knew. I let it happen, and I sent what the shield didn't use up the hill.`,`That's the answer. If you have another question, ask it now.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`},{...i(`The Man Becoming Weather`,`The storm floor, lightning walking Raiko's shoulders like gulls`,`Kage Raiko Veyr`,[`You're looking at the lightning. I can feel it too.`,`It started a few years ago. I lose my temper at doors, at the sea, at people who aren't there. Last week I broke a mirror and couldn't remember doing it.`,`The engine is changing me. I knew it would. I thought I had more time.`,`That's enough talking. The payment is due, and the board is blank. Step forward.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`Step onto the storm floor.`,nextPage:19}]},{...i(`The Quiet Storm`,`The storm floor, Kesa's cable maps unrolled on the rail`,`Kage Raiko Veyr`,[`Let me see that. Hold it down.`,`This is Kesa Volt's ridge line. It crossed my desk twelve years ago. The council called it grief, and I signed the refusal.`,`You built it? The Low Terraces made it through the first arm with the engine off?`,`All right. Show me exactly what happened.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`"Three hundred roofs. One district. Engine cold. And the district SAW it hold."`,nextPage:5,requireTrait:`sv88-woke-the-district`},{text:`Open Vanta's storm log to the signed pages and read him every line.`,nextPage:6,requireTrait:`sv88-logged-the-storm`},{text:`"Your own odds-runners moved the line. The board already believes it."`,nextPage:7,requireTrait:`sv88-baited-the-board`},{text:`Set the anchor splice on the rail and let the wind sing through it.`,nextPage:8}]},{...i(`What the District Saw`,`The storm floor, the Low Terraces' lamps visible far below`,`Kage Raiko Veyr`,[`Three hundred families saw it hold. I sent people down there to check because I didn't believe the first report.`,`The engine was off. No intake at all.`,`I can't dismiss that as luck.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He looks to the turning sky.`,nextPage:15}]},{...i(`The Signed Log`,`The storm floor, Vanta's log flat under Raiko's wide hand`,`Kage Raiko Veyr`,[`Give me the log.`,`Wind load at the anchors. Nothing drawn at the junctions. Roof counts every hour. Vanta signed every page?`,`Damn him.`,`No. I'm not arguing with the figures. They hold.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He sets the log down.`,nextPage:15}]},{...i(`The Board's Own Odds`,`The storm floor, a torn odds slate spinning in the wind between you`,`Kage Raiko Veyr`,[`I saw the odds change at dawn. I told myself a clerk had made a mistake.`,`Then they changed again.`,`The board expects the Low Terraces to survive without the engine. So do the people betting their own money.`,`I understand what that means.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He lets the torn slate spin away.`,nextPage:15}]},{...i(`The Splice`,`The storm floor, the anchor splice knotted to the rail, holding`,`Kage Raiko Veyr`,[`That's her splice. I remember it from the plans.`,`It held through the first arm?`,`I signed those plans away without leaving my desk.`,`Put it here. I want to see the knot.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He rests two fingers on the splice.`,nextPage:15}]},{...i(`Her Daughter Says the Why`,`The gate stair door banging open, Mira crossing the storm floor`,`Mira Volt`,[`%name, step back. I need to do this myself.`,`Her name was Kesa Volt. She was my mother. Your board used her grief for six years and kept using her name after she died.`,`She wrote down her reason. I'm going to read it.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`Let her say the why.`,nextPage:10}]},{...i(`The Reason, Kept`,`The storm floor, Mira reading from a slate that never reached the shaft`,`Mira Volt`,[`'I am angry because I warned the council the low moorings would fail, and they laughed, and my husband drowned at the low moorings. I am angry because my grief was posted as entertainment. I am angry because anger is all of him I have left, and this village keeps trying to collect it.'`,`That's what she wrote.`,`Her account is closed. You're not taking anything else from her.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`The Kage looks at the slate a long time.`,nextPage:11}]},{...i(`The Bookmaker's Silence`,`The storm floor, the wind oddly gentle for a breath`,`Kage Raiko Veyr`,[`I should have listened to her twelve years ago.`,`I don't have a defense for that.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He looks at the slate a moment longer.`,nextPage:15}]},{...i(`A Sky Without a Why`,`The storm floor, the district's lamps below, the maps not in your hands`,`Kage Raiko Veyr`,[`The Low Terraces held. I can see that.`,`But you haven't shown me the design or told me who made it. I don't know if it can protect the rest of the village.`,`One district surviving one night is not enough for me to shut down the engine.`,`Bring me the rest, or fight me.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He turns back to the storm.`,nextPage:19}]},{...i(`The Answer in Your Kit`,`Kesa's maps unrolled in Raiko's scarred hands`,`Kage Raiko Veyr`,[`These are Kesa Volt's plans. They're built, tested, and protecting three hundred eleven roofs.`,`And you still have her reason in your coat.`,`You found it in the ravine, carried it all this way, and never gave it to her daughter.`,`Maybe you meant to keep it safe. So did I.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He rolls the maps with terrible care.`,nextPage:19}]},{...i(`Vanta Opens the Books`,`The storm floor, an old bookmaker setting ledgers on the rail one by one`,`Elder Vanta`,[`Move aside. I need to say this.`,`These are my records, Raiko. Every bout I arranged and every share I took. I started matching the fights the tower requested thirty years ago.`,`I knew the floor was taking something. I chose not to ask how much.`,`Put my name beside yours. I helped you do it.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`He sets the last ledger down.`,nextPage:19}]},{...i(`The Last Answer`,`The storm floor, Raiko looking from the proof to the turning sky`,`Kage Raiko Veyr`,[`All right. I have no storm left to answer with.`,`Let's find out what still stands when mine is gone.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`Enough. The storm decides now.`,nextPage:19}]},{...i(`Answer for the ninth share. You've been drawing it for seasons.`,`The reckoning`,`Kage Raiko Veyr`,[`You took the elders' cut. Then you know how easy it is to accept the money and stop asking where it came from.`,`Did you ever look at two angry people and think their fight would cover the month? I did.`,`You carried that responsibility for two seasons. I've carried it for thirty years. That doesn't excuse me. It does mean I know how quickly a person gets used to it.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`Enough. The storm decides now.`,nextPage:19}]},{...i(`Answer for the routing mark. My bout was written before I fought it.`,`The reckoning`,`Kage Raiko Veyr`,[`The Pike bout was fixed. You were supposed to lose in the third exchange. I approved it.`,`Your slate came back blank three times. A clerk was punished because I assumed the error was theirs.`,`The board can't predict you. I don't know why. But don't stand there and pretend I had no choice because the board could predict me.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`Enough. The storm decides now.`,nextPage:19}]},{...i(`Answer for Kesa Volt. Her line holds your sky right now.`,`The reckoning`,`Kage Raiko Veyr`,[`I knew the report as soon as you put it in front of me. Twelve years ago I called it grief and sent it back.`,`I tested one section later, alone. It held through winter. I buried the result because if Stormveil stopped needing the Engine, Hollow Gate stopped being fed.`,`Her anchors are holding this tower now. Tell Mira I knew they could. I don't have a cleaner version of that.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,choices:[{text:`Enough. The storm decides now.`,nextPage:19}]},{...i(`The Blank Board`,`The storm floor, the last blank slate between you and the Tyrant rising`,`Kage Raiko Veyr`,[`Enough. Bell's up.`,`I've kept this village alive for thirty years. I'm not stepping aside because one plan worked for one night.`,`The board is blank, and the debt is due. Last slate in Stormveil, Jonin. It's yours.`,`Show me what fights when the reasons are free.`]),image:`/scenes/story/story-stormveil-village-100-8.webp`,leftName:`Player`,rightName:`Kage Raiko Veyr`,rightImage:`/portraits/kage-raiko-veyr-hollow.webp`,choices:[{text:`Show him the quiet storm.`,nextPage:4,requireTrait:`sv88-better-storm-carried`},{text:`Let Mira say her mother's reason.`,nextPage:9,requireTrait:`sv88-better-storm-deferred`},{text:`Let Vanta answer for the ninth share.`,nextPage:14,requireTrait:`sv92-witness-present`},{text:`Show him Kesa's answer from your kit.`,nextPage:13,requireTrait:`sv88-unfinished-answer`,forbidTrait:`sv88-better-storm-ready`},{text:`Show him the district that held.`,nextPage:12,requireTrait:`sv88-line-held`,forbidTrait:`sv88-reason-proof-any`},{text:`Answer for the ninth share. You've been drawing it for seasons.`,nextPage:16,requireTrait:`sv58-took-the-cut`},{text:`Answer for the routing mark. My bout was written before I fought it.`,nextPage:17,requireTrait:`sv70-read-the-mark`},{text:`Answer for Kesa Volt. Her line holds your sky right now.`,nextPage:18,requireTrait:`sv88-reason-proof-any`}]}],[{text:`Refuse the challenge. Out loud. Before everyone. Then break the board.`,conclusion:`You say no where the whole square can hear it, then drive your fist through the blank board. Every posted account comes due at once. Reasons return to people who had forgotten they owned them. The crowd breaks into shouting, crying, and stunned silence. Under the arena the cistern pulls once, finds every account already claimed, and goes still. Up the hill, Hollow Gate's Stormveil quarter comes up dry. Raiko looks at the wild sky, laughs, and attacks.`,trait:`honorable`},{text:`Accept the bout. After it, the valve gets a meter, a law, and a watch.`,conclusion:`You state the terms into the record: after tonight the floor takes nothing without consent, witnesses, and a meter anyone can read. The crowd is quieter than it was for the refusal. Raiko nods once. The cistern opens on its old schedule, finds no posted name and no witness, then shuts again. Hollow Gate waits on consent Stormveil has finally learned it can withhold. Raiko calls the storm and attacks.`,trait:`suspicious`},{text:`The seat, the valve, the ledger. Mine.`,conclusion:`You post the only slate that was ever going to satisfy you: your own name, for the seat itself. The board accepts before the chalk dries; it has been grooming this account since the night it posted you twice. Raiko's grin comes back one last time, wide and terrible and relieved. 'Then win it,' says the storm, with his voice. The cistern does not go still for you. It holds its breath, four villages' worth of banked tribute, and waits, patient as arithmetic, for its new seat to post the first thing it will drink.`,trait:`ambitious`}])],"Ashen Leaf Village":[a(`Ashen Leaf Village`,4,`Roots of the Shinobi`,`Wooden Root Guardian`,`🌿`,[{...i(`The Register Hall`,`Register hall, morning light through cedar smoke`,`Toma Reed`,[`First time signing? Stand here, next to me. If you stand in the middle of the hall, the clerks think you have something to hide.`,`I'm Toma. Toma Reed, grove squad. I've done this four times, so you're in good hands.`,`Name, family, craft. Then what you intend to become.`,`My brother told me to answer the last one smaller than the truth.`,`I laughed at him. Don't do that.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`},{...i(`The Fourth Question`,`The Register wall, quill waiting`,`Narrator`,[`The Register is a wall of living cedar wood, forty strides long. Every person in the village has their own line carved into it, holding their name and their answers.`,`The clerk dips the quill and hands it to you.`,`The hall is very quiet, the way a forest is quiet when something large is walking through it.`,`What do you intend to become?`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`,choices:[{text:`"I want to protect people."`,nextPage:2,trait:`al4-become-protector`},{text:`"I want to become the strongest shinobi alive."`,nextPage:3,trait:`al4-become-strongest`},{text:`"I want to build something that outlasts me."`,nextPage:4,trait:`al4-become-builder`},{text:`"I want to uncover what people hide."`,nextPage:5,trait:`al4-become-seeker`},{text:`"I don't know yet."`,nextPage:6,trait:`al4-become-unknown`}]},{...i(`A Protector`,`The Register wall`,`Registry Duty Clerk`,[`A protector. All right.`,`The ink went deeper than usual. I haven't seen that in a while.`,`You're signed in, %name. Welcome to Ashen Leaf.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`,choices:[{text:`Step back from the wall.`,nextPage:7}]},{...i(`The Strongest`,`The Register wall`,`Registry Duty Clerk`,[`The strongest shinobi alive. That's a large answer.`,`The ink went deep. I don't know whether that's good.`,`You're signed in, %name. Welcome to Ashen Leaf.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`,choices:[{text:`Step back from the wall.`,nextPage:7}]},{...i(`A Builder`,`The Register wall`,`Registry Duty Clerk`,[`Something that outlasts you. Good.`,`Someone gave me almost the same answer years ago. Keep your drawings somewhere safe.`,`You're signed in, %name. Welcome to Ashen Leaf.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`,choices:[{text:`Step back from the wall.`,nextPage:7}]},{...i(`A Seeker`,`The Register wall`,`Registry Duty Clerk`,[`You want to uncover what people hide. You know you're saying that in the records hall, right?`,`No, don't change it. I'll write what you said.`,`You're signed in, %name. Welcome to Ashen Leaf.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`,choices:[{text:`Step back from the wall.`,nextPage:7}]},{...i(`Not Yet`,`The Register wall`,`Registry Duty Clerk`,[`You don't know yet. That's fine.`,`The quill keeps catching on your line. Strange.`,`I'll put 'undecided.' If you change your mind, come back. Welcome to Ashen Leaf, %name.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`,choices:[{text:`Step back from the wall.`,nextPage:7}]},{...i(`The Black Flower`,`The Register wall, ink drying`,`Toma Reed`,[`Good, you're done. Now we get honey bread. There's a cart by the south arch that sells the good kind, and after a signing you deserve...`,`Wait.`,`Look at your line. Something is growing out of your line.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`},{...i(`Elder Mori`,`The Register wall, a crowd gathering`,`Elder Mori`,[`Move aside, please. Thank you.`,`It's a black flower. The Register grows one when it sees unusual potential.`,`I've seen two in forty years. People will congratulate you. There will be too much bread.`,`Enjoy that if you can. Just don't assume the flower is a gift.`,`Come with me. You have a grove trial before sundown.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`,choices:[{text:`Follow Mori to the grove.`,nextPage:9}]},{...i(`The Grove Trial`,`The old grove, roots breaking the flagstones`,`Elder Mori`,[`The rule of the grove is simple. The ash of every record keeper before me was mixed into this soil, and the Guardian grew out of it. When you fight it, you are fighting the village's dead.`,`They will test what you are, not what you said at the wall. The dead always know the difference.`,`Toma, stop hiding behind the new one. You have passed this trial. Act like it.`,`Begin when you are ready. The roots are patient. I am seventy, and less so.`]),image:`/scenes/story/story-ashen-leaf-village-4-0.webp`}],[{text:`Bow low to the roots first, and mean it.`,conclusion:`Mori raises his eyebrows. The Guardian rises out of the soil slowly, almost politely, like an old keeper getting up to greet a guest.`,trait:`honorable`},{text:`Watch the Guardian's pattern before you move.`,conclusion:`It circles the way roots grow, in slow spirals that repeat. By the second pass you know its rhythm. Behind you, Mori murmurs that in forty years, nobody thought to just watch it first.`,trait:`suspicious`},{text:`Strike first. Show the grove what's growing.`,conclusion:`Toma makes a sound like a kettle boiling over. The Guardian catches your first blow and the whole yard shakes, and somewhere under the soil, something old starts paying attention.`,trait:`reckless`}]),a(`Ashen Leaf Village`,15,`The Forbidden Seed`,`Rootbound Guard Initiate`,`🌿`,[{...i(`The Blessing`,`Ash-house row at dawn, neighbors gathering`,`Narrator`,[`Overnight, black flowers opened along a fence in ash-house row. Eleven of them, glossy as beetle shells, in a straight and tidy line.`,`The neighbors are bringing honey bread and congratulations. Flowers on a fence mean the same thing as a flower on the Register wall: someone in that house could become something extraordinary.`,`Toma is standing at the edge of the crowd, and he is not eating his honey bread.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`},{...i(`Eleven Flowers`,`The fence line, crowd thinning`,`Toma Reed`,[`That's Imera's house. Her daughter Sena is nine. She builds water wheels from barrel scraps and a loom that walks across the table.`,`We had flowers on our fence when I was little. Everyone brought us bread.`,`My brother changed that spring.`,`I haven't said that before. Look, the Kage is here.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`},{...i(`The Kage at the Fence`,`Imera's gate, winter bundles stacked`,`Kage Hoshina Enju`,[`Imera. I brought your winter share early. There's extra because half the village will eat your food this week.`,`You must be Sena. I heard you built a walking loom. May I see it?`,`It limps. I like that. You made this by yourself?`,`The survey comes tomorrow. Get some rest tonight.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`},{...i(`What the Village Says`,`The gate, Hoshina's guards moving on`,`Imera`,[`Hoshina kept this village alive. No child has frozen here since she became Kage. My mother reminds us every winter.`,`She remembered Sena's name.`,`So why am I afraid of those flowers?`,`There are eleven. Nobody gets eleven. I asked Jorun how many his family had, and he couldn't remember any.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`,choices:[{text:`Go find Mori.`,nextPage:4}]},{...i(`Mori Counts`,`The register annex, bloom charts on the table`,`Elder Mori`,[`Good. I need both of you on ash-house row tonight. The survey arrives at first light.`,`Most houses get one flower, sometimes two. I've never recorded eleven.`,`Don't let anyone touch them. That includes the family.`,`If something happens, come to me before you speak to the survey.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`,choices:[{text:`Take the night watch.`,nextPage:5}]},{...i(`The Night Watch`,`The fence line, moonless`,`Narrator`,[`Past midnight, the row is quiet. Cricket song, cold ash smell, eleven flowers holding a faint shine like they are being read by some faraway light.`,`The door of the blessed house opens, softly. Imera slips out into her own garden.`,`She is carrying garden shears.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`,choices:[{text:`Step out and stop her, gently.`,nextPage:6},{text:`Stay hidden and watch what she does.`,nextPage:7}]},{...i(`Imera's Shears`,`The fence line`,`Imera`,[`Please. You can still pretend you didn't see me.`,`My aunt had flowers too. She could sing in three languages. Then one spring she stopped singing unless somebody asked. After a while she stopped completely.`,`Nobody in my family thinks that's strange. I do.`,`I'm going to cut one or two before the survey arrives. Maybe they'll record a smaller blessing and leave Sena alone.`,`Give me one minute. That's all I'm asking.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`,choices:[{text:`Dawn is coming. Decide.`,nextPage:8}]},{...i(`The Longest Cut`,`Behind the rain barrel`,`Narrator`,[`She kneels at the fence and does not cut. Not at first. She counts the flowers twice, the way you count sleeping children.`,`Then she chooses the largest bloom, the one nearest Sena's window, and holds the shears against its stem for a long time without closing them.`,`Beside you, Toma whispers: 'That's how my mother stands at my brother's workbench. Like she's looking for something she can't name.'`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`,choices:[{text:`Dawn is coming.`,nextPage:8}]},{...i(`First Light`,`The row at dawn, survey banners approaching`,`Toma Reed`,[`The survey is early. There's a Rootbound Initiate walking out front. They always send one where there are flowers. Official word is that it guards the blessing.`,`Imera is still at the fence. The shears are in her apron. The big flower is still on its stem.`,`If the survey records her standing there with shears, this stops being about flowers.`,`Whatever you're going to do, the next thirty steps are when you do it.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`},{...i(`The Survey Arrives`,`The gate, the Initiate's staff already glowing`,`Narrator`,[`The Initiate plants its staff at the gate and begins the recording chant. Under the fence, roots stir like fingers under a blanket.`,`Imera looks at you once, quickly, the way people look at weather before a journey.`,`Eleven flowers shine in a tidy line, and the largest one leans toward a child's window.`]),image:`/scenes/story/story-ashen-leaf-village-15-1.webp`}],[{text:`Palm the cut stem before the chant reaches it.`,conclusion:`One quick snip, hidden in your sleeve, smooth as a card trick. The survey records ten blooms and Imera's shoulders come down an inch. The Initiate pauses over its count, then turns its head toward you.`,trait:`suspicious`},{text:`Stand between Imera's gate and the survey.`,conclusion:`The chant falters. Initiates are not trained for a person who simply will not move. Behind you, Imera whispers thank you, and then she whispers run.`,trait:`honorable`},{text:`Tear the big flower out, roots and all, in the open.`,conclusion:`The bloom comes up with a sound like a struck bell, and every root in the row wakes at once. Toma shouts your name. At least nobody can pretend it was an accident.`,trait:`reckless`}]),a(`Ashen Leaf Village`,25,`The Cut Branches`,`Archive Spirit of the Root`,`🌿`,[{...i(`After Hours`,`The archive, one lamp between the stacks`,`Toma Reed`,[`Everything from the Register is copied here. Letters and drawings too.`,`I have a key because I repair the shelves. I took the job because I wanted the key.`,`I need someone else to look at this and tell me whether I'm imagining it.`,`Start with Jorun's record. Tell me what he was building.`]),image:`/scenes/story/story-ashen-leaf-village-25-2.webp`},{...i(`Jorun's Plans`,`The carpenter's slat, held to the lamp`,`Narrator`,[`The record is complete. An apprenticeship, a marriage, a workshop by the mill. Then drawings: a bridge across the flood channel, drawn with a sure and hungry hand. Three lines of it.`,`The bridge drawings stop mid-line. The very next entry is a cabinet. Then chairs. Then twenty years of chairs.`,`The ink of the first chair is exactly as old as the ink of the unfinished bridge.`]),image:`/scenes/story/story-ashen-leaf-village-25-2.webp`,choices:[{text:`Pull Aren Reed's slat yourself.`,nextPage:4},{text:`Ask Toma what happened to the bridge.`,nextPage:2},{text:`Ask Mori. He owes you for the border.`,nextPage:3,requireTrait:`rd22-sealed-for-mori`}]},{...i(`The Bridge`,`Between the racks`,`Toma Reed`,[`Jorun is still alive. He drinks at the mill house most nights. If you ask him about the flood channel, he laughs and says bridges were never his thing.`,`But you saw the drawings. He cared about that bridge.`,`Then the drawings stop and he spends twenty years making chairs. He doesn't remember wanting anything else.`,`Inside some of these racks, somebody carved the word 'pruned.' I don't think they meant the orchards.`]),image:`/scenes/story/story-ashen-leaf-village-25-2.webp`,choices:[{text:`Ask about Aren.`,nextPage:4}]},{...i(`A Quiet Debt`,`Mori's desk, lamp turned low`,`Elder Mori`,[`You kept the border business quiet. I remember. What do you want to know?`,`Jorun. Yes. I remember the bridge. I surveyed his household myself, the same spring he stopped drawing it.`,`The official record says he changed his mind. I don't believe that anymore.`,`Read Aren Reed's record tonight. Don't tell Toma I sent you.`]),image:`/scenes/story/story-ashen-leaf-village-25-2.webp`,choices:[{text:`Pull Aren's slat.`,nextPage:4}]},{...i(`Aren Reed`,`The Reed family rack`,`Toma Reed`,[`Here. Aren Reed. My brother. Read it. Nothing is missing from it. That's what I need you to understand first.`,`It says he was quiet and dutiful. It even describes his smile correctly.`,`My mother remembers him that way too.`,`But he wasn't quiet. He argued with everybody. I have proof at home. I'm not ready to show you yet.`]),image:`/scenes/story/story-ashen-leaf-village-25-2.webp`},{...i(`The Archive Wakes`,`The stacks, lamp guttering`,`Narrator`,[`The racks creak. Not the creak of wood settling. The creak of something heavy turning over in its sleep.`,`Down the aisle, the slats you pulled tonight begin sliding back into their places. Gently. Tidily. By themselves.`,`The Archive Spirit is the keeper of this room. It guards every record here, including the cut ones, and you have spent the night picking at its stitches.`]),image:`/scenes/story/story-ashen-leaf-village-25-2.webp`},{...i(`The Keeper of Copies`,`The archive aisle, roots sliding from the walls`,`Toma Reed`,[`Okay. That's the archive's keeper. It's old, it's strong, and we are very much not supposed to be in here at night.`,`It won't follow us past the door. Probably. I mend its shelves and it tolerates me, but you pulled records, and it takes that personally.`,`One rule, whatever happens: the slats stay in this room. If we carry one out, the survey knows by noon and this whole night becomes evidence against us.`,`It's reaching for you. Decide.`]),image:`/scenes/story/story-ashen-leaf-village-25-2.webp`}],[{text:`Copy Aren's page by lamplight while it comes.`,conclusion:`Your hand stays steady and your letters come out ugly and complete. The Spirit takes the slat back from under your quill with terrible patience, and the copy in your sleeve is yours to keep.`,trait:`suspicious`},{text:`Hold the keeper off Toma. He copies faster.`,conclusion:`It hits like a falling shelf. Toma scribbles and swears and keeps scribbling. When you finally go down on one knee, he is finished, and he drags you out the door with the copy in his teeth.`,trait:`reckless`},{text:`Set the slat down and face the Spirit with open hands.`,conclusion:`It stops one root-length away. Whatever it reads people against, it reads you twice, and finds the same impossible thing the Register wall found. It lets you both walk to the door. It keeps the slat.`,trait:`honorable`}]),a(`Ashen Leaf Village`,35,`The Rootfire Chamber`,`First Flame Sentinel`,`🌿`,[{...i(`The Kiln Stair`,`Beneath the ancestral kiln, heat rising`,`Elder Mori`,[`Stay on the stairs. The floor down here is older than the village, and I do not trust it.`,`I decided you needed to see this. If anyone objects, they can come to me.`,`The Rootfire is below us. The founders lit it four hundred years ago. It has kept the village warm ever since.`,`Put your gloves on. I need to show you two different rooms.`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`},{...i(`The Founders' Alcove`,`A carved alcove, offerings behind wax`,`Narrator`,[`The alcove is small and heartbreakingly neat. Wooden tokens rest in carved niches, each one shaped by hand: a little ship, a house, a wedding ring, a book.`,`Each token is signed. Big, careful signatures, the kind people write when the writing is the last thing they will do about it.`,`The same phrase appears on every one, in forty different hands: 'My green years, given gladly.'`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`,choices:[{text:`Read a founder's token aloud.`,nextPage:2},{text:`Ask Mori what the tokens actually are.`,nextPage:3},{text:`Whisper to Toma: is this the room from Aren's letter?`,nextPage:4,requireTrait:`toma-hope`}]},{...i(`Given Gladly`,`The alcove`,`Elder Mori`,[`'I, Osu of the mill line, give the roads I will not walk and the sons I will not meet. Gladly. Keep the children warm.'`,`You read it well. Most people's voices fail on the word gladly.`,`Osu was real. That token bought the east wall, more or less. He lived to ninety, never married, and by every record we have, he never once regretted his gift. That is what this room used to be.`,`Used to be. Now walk twenty steps to your left, and see what it is.`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`,choices:[{text:`Walk to the racks.`,nextPage:5}]},{...i(`The Gift`,`The alcove`,`Elder Mori`,[`Each token represents a future someone gave up. The Rootfire turned it into heat, medicine, and material for the walls.`,`The founders volunteered. They were adults, and they were told what it would cost them.`,`I was proud of this room for thirty years.`,`Now look at the racks on the left.`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`,choices:[{text:`Walk to the racks.`,nextPage:5}]},{...i(`Aren's Map`,`The alcove, out of Mori's hearing`,`Toma Reed`,[`This is the room from Aren's letter. He wrote that the fire was fed twice. I thought he meant the kiln had two doors.`,`He drew a map on the back. Stairs, alcove, then racks. Under the racks he wrote 'stamped.'`,`There's a quartered circle beside it. I thought it was part of his water-screw.`,`It isn't.`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`,choices:[{text:`Walk to the racks.`,nextPage:5}]},{...i(`The Second Feeding`,`Iron racks, fresh graft-slats in rows`,`Narrator`,[`Twenty steps left, the hand carving stops and the iron begins. Racks from floor to ceiling, loaded with pale wooden slats.`,`No signatures on these. Each slat carries a stamp instead: a household mark, a season, and one small tidy character that means 'approved.'`,`The nearest slat still smells of fresh sap. Somebody's future was cut this week, without their name on it, and the fire is drawing warmth from it while you stand here.`,`And there is a wrongness you feel before you can name it. When the signed founders' tokens burn, their ash lifts UP: into the flue, into the mortar, into the warm old bones of the village.`,`The stamped slats burn differently. Their smoke rises, yes, enough to keep the room alive, enough to keep the lie useful. But the ash does not rise. It falls, through a grate beneath the racks, down into a black seam under the kiln. Fire is not supposed to drain. Mori watches it fall, and for once the record keeper has no quick answer ready.`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`},{...i(`The First Flame Sentinel`,`The threshold, an armored shape kindling`,`Elder Mori`,[`Don't move. Don't draw your weapon.`,`The founders built that Sentinel to keep thieves away from their gifts. It asks whether you gave or took.`,`Survey crews carry permits, and the Sentinel accepts them. I've watched them bring stolen futures past it and said nothing.`,`I didn't bring a permit tonight.`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`,choices:[{text:`Face the Sentinel.`,nextPage:7}]},{...i(`Did You Give, Or Did You Take`,`The threshold, the Rootfire at your back`,`Narrator`,[`The Sentinel's visor opens on old fire. It looks at Mori for a long moment, and lowers its head like it is grieving with him.`,`Then it looks at you, and stops. Whatever it measures people against, you come back unreadable, and unreadable is not on its list of permitted things.`,`Its blade arm wakes with a sound like a kiln door opening. It is not wrong to guard this place. That is the terrible part.`]),image:`/scenes/story/story-ashen-leaf-village-35-3.webp`}],[{text:`Douse the nearest rack line and see what happens.`,conclusion:`Steam screams up the flue and half the chamber's warmth dies at once. Far above, faint through the stone, you hear the village notice the cold. The Sentinel moves toward you, and for one strange moment it seems to approve.`,trait:`reckless`},{text:`Count the stamps. Every household. Every season.`,conclusion:`You reach forty one households before the Sentinel closes the distance. Forty one, in this season alone. Mori watches you count, and every rack seems to age him another year.`,trait:`suspicious`},{text:`Demand Mori say who signs the approvals.`,conclusion:`'One hand,' he says, not looking away from the fire. 'The same hand for thirty years.' The Sentinel hears the answer too, and its grief sharpens into something with edges.`,trait:`honorable`}]),a(`Ashen Leaf Village`,50,`The Branch That Rises`,`Jonin Trial: Rootbound Master`,`🌿`,[{...i(`The Measuring`,`The graft hall, ribbons and calipers`,`Registry Duty Clerk`,[`Arm out, please. Now the other one. Chin level, eyes on the wall mark.`,`Height, reach, span of hand. The tailors want your measurements for the Jonin grays, and the Register wants them for the record. Between you and me, the Register asks for more measurements than any tailor I've ever met.`,`You're the black flower signing. The whole hall has been talking about it. Don't let it swell your head. Flowers wilt. Paper keeps.`,`There, done. Measured like a cutting, as the old joke goes. Nobody remembers it's a joke about grafting. The rite is at the bell. Don't be late. The Kage is attending in person.`]),image:`/scenes/story/story-ashen-leaf-village-50-4.webp`},{...i(`Before the Bell`,`The hall steps, Toma pacing`,`Toma Reed`,[`You're really doing this. I'd be happier if I weren't about to be sick.`,`The old records call this rite 'the grafting.' Nobody says that anymore.`,`Listen for the third line of the oath: 'I will grow where the tree permits.'`,`Say whatever keeps you safe. Just know Aren took the same oath.`]),image:`/scenes/story/story-ashen-leaf-village-50-4.webp`,choices:[{text:`Answer the bell.`,nextPage:2}]},{...i(`The Grafting`,`The rite circle, Hoshina presiding`,`Kage Hoshina Enju`,[`Come forward.`,`The village is proud of you. You are the strongest shinobi this hall has seen in a generation.`,`The oath is short. Service to the village, silence when required, and the final line.`,`Repeat it after me.`]),image:`/scenes/story/story-ashen-leaf-village-50-4.webp`,choices:[{text:`Swear it plainly, every word.`,nextPage:3},{text:`Ask what happens to branches that grow past permission.`,nextPage:4},{text:`Change the third line: swear to the village, not the tree.`,nextPage:5}]},{...i(`Word for Word`,`The rite circle`,`Kage Hoshina Enju`,[`'I will grow where the tree permits.' You didn't hesitate.`,`I don't know whether you meant it. I expect I'll find out.`,`Rise, Jonin of Ashen Leaf.`,`The village will be watching you closely from now on.`]),image:`/scenes/story/story-ashen-leaf-village-50-4.webp`,choices:[{text:`Rise as Jonin.`,nextPage:6}]},{...i(`The Question`,`The rite circle, the hall holding its breath`,`Kage Hoshina Enju`,[`No one has asked me that during the rite in forty years.`,`If someone becomes dangerous to the village, I decide what happens to them.`,`Sometimes I remove them. You already knew that, or you wouldn't have asked.`,`Take the oath. Don't make me decide that about you.`]),image:`/scenes/story/story-ashen-leaf-village-50-4.webp`,choices:[{text:`Take the oath and rise.`,nextPage:6}]},{...i(`The Substitution`,`The rite circle`,`Kage Hoshina Enju`,[`'I will grow where the village needs me.' The village. Not the tree.`,`That is not the oath.`,`No. Leave it. Clerk, record exactly what was said.`,`Rise, Jonin. I want you where I can see you.`]),image:`/scenes/story/story-ashen-leaf-village-50-4.webp`,choices:[{text:`Rise as Jonin.`,nextPage:6}]},{...i(`The Trial of the Rootbound Master`,`The rite circle, floor roots parting`,`Narrator`,[`The floor opens on old root-worked steps. Rank in Ashen Leaf is not handed over. It is tested in the dark, against the Rootbound Master, the grafted champion of the last generation.`,`Hoshina watches from the rim with her hands folded, unhurried, like a keeper watching weather roll in.`,`Somewhere in the crowd, Toma is mouthing the words 'you said WHAT' and holding both thumbs up anyway.`]),image:`/scenes/story/story-ashen-leaf-village-50-4.webp`}],[{text:`Fight carefully. Give the watchers nothing to write down.`,conclusion:`You win the way clerks write: neat, spare, nothing extra for the record. Hoshina tilts her head. 'Restraint,' she tells the hall, 'grafts well.' You spend the rest of the day wishing she had said anything else.`,trait:`suspicious`},{text:`Fight as yourself, whatever it shows them.`,conclusion:`It is loud and messy and entirely yours, and halfway through, the old Master laughs out loud like a man remembering what being alive felt like. When you rise, the hall is cheering, and the black flower on the Register glows through the floor above.`,trait:`honorable`},{text:`End it fast. Break the Master's stance in three moves.`,conclusion:`The hall gasps at the speed and misses what you saw up close: the Master's relief. Grafted champions do not get to retire. Now the village needs a new one, and every eye in the hall lands on you.`,trait:`reckless`}]),a(`Ashen Leaf Village`,65,`The Mission of Quiet Ash`,`Rootbound Retrieval Squad`,`🌿`,[{...i(`Escort Orders`,`The register annex, crates on a wagon`,`Registry Duty Clerk`,[`Jonin. Good, you're punctual. Escort assignment: six crates of seasoned offerings, from this annex to the kiln, before the frost arrives. Signed by the Kage's own office.`,`The crates are sealed and blessed. That means nobody opens them. The last escort who opened one has spent a season pulling weeds on the terraces, and he was LUCKY.`,`You come recommended, if that matters to you. Mori cleared you for sealed work personally.`,`Take the Reed boy with you. He's due for a route, and frankly, I'd rather he was next to somebody level-headed this week.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`,choices:[{text:`Sign for the crates and move out.`,nextPage:3},{text:`Ask why offerings need a Jonin escort.`,nextPage:1},{text:`You've read Mori's charts. Ask which households packed these.`,nextPage:2,requireTrait:`al58-took-the-knowledge`}]},{...i(`A Fair Question`,`The annex`,`Registry Duty Clerk`,[`Because last month, a crate went missing between here and the kiln. The month before that, two.`,`The official wording is that somebody is stealing blessings. I keep my job by using official wordings.`,`You want my private wording? Somebody in this village is a thief with excellent taste in what to steal, and half the annex packs the crates slowly on purpose, and you did not hear either of those things from me.`,`Sign. The frost doesn't care which wording is true.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`,choices:[{text:`Sign and move out.`,nextPage:3}]},{...i(`The Charts`,`The annex, voice low`,`Registry Duty Clerk`,[`So you HAVE read Mori's charts. I wondered why he cleared you so fast.`,`Fine. Lean in. Crate two came from the mill line. Crate three is the weaver who petitioned for a school last spring. Crates five and six came out of the detention rows, and I wasn't here when they were packed, because I made sure I was needed elsewhere.`,`I file things. I don't choose them. Some mornings that sentence is the only thing holding my roof up.`,`Sign, Jonin. And if you walk slowly past the mill, I won't be the one who noticed.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`,choices:[{text:`Sign and move out.`,nextPage:3}]},{...i(`The Kiln Road`,`The forest road, wagon wheels loud`,`Toma Reed`,[`Aren would have opened these before the second mile marker.`,`The third crate rattles when we hit a rut. Ash and cedar slats don't make that sound.`,`Before I ask this, are you my commanding officer or my friend?`,`There's a pry bar under the seat.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`,choices:[{text:`Pull the wagon off the road. Open the crate.`,nextPage:5},{text:`Keep rolling. The seals stay on.`,nextPage:4}]},{...i(`Sealed`,`The wagon, still rolling`,`Toma Reed`,[`Right. Sealed. You're right. Forget I said anything.`,`There. That was a little wooden wheel. I built toys with Aren for ten years. I know the sound.`,`Stop the wagon. You can report me afterward.`,`I can't deliver a child's toy to that fire. Please.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`,choices:[{text:`Pull off the road.`,nextPage:5}]},{...i(`The Third Crate`,`Off the road, crate open`,`Narrator`,[`Not ash. Not slats.`,`A model water-screw with one cracked vane, built small enough to hold. A bundle of letters tied with weaver's thread. Seed jars labeled in a child's careful hand. And a little wooden loom, half folded, that stirs in the straw and goes still, like it knows to hide.`,`A whole crate of what people were going to become, packed in straw, stamped 'approved,' and addressed to a fire.`,`Toma picks up the loom and holds it the way you hold a bird.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`,choices:[{text:`Wrap the water-screw and hide it on your person.`,nextPage:6,trait:`al65-saved-the-screw`},{text:`Give the loom to Toma. He'll know whose it is.`,nextPage:6,trait:`al65-gave-toma-the-loom`},{text:`Repack everything exactly as you found it.`,nextPage:6,trait:`al65-resealed-the-crate`}]},{...i(`The Manifest Under the Ash`,`Off the road, a folded paper under the second crate's false bottom`,`Toma Reed`,[`This was under the false bottom. It's a shipping manifest.`,`It says: graft-slats, late season, destination Fifth Anchor escrow. The buyer's mark is a circle cut in four.`,`At the bottom: 'Deliver surplus below Rootfire intake.'`,`There's something under the fire. Whatever the village doesn't use is being sent there.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`,choices:[{text:`Pocket the manifest.`,nextPage:7,trait:`al65-found-gate-manifest`}]},{...i(`The Retrieval Squad`,`The road behind, lanterns through the trees`,`Toma Reed`,[`Lanterns, kiln side. That's a Rootbound Retrieval Squad. They sweep the route whenever a shipment stalls too long.`,`We have six crates and one wagon. They're coming from behind us.`,`The manifest is the only thing we have that connects the shipment to the Kage's office.`,`Decide now.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`},{...i(`Lantern Light`,`The kiln road, squad closing`,`Narrator`,[`The lanterns spread out through the trees the way trained squads spread: unhurried, certain, closing from three sides.`,`In crate five, paper shifts softly, like letters turning over in their sleep.`,`The frost is coming. The fire is warm. And everyone on this road tonight is somebody's future, one way or the other.`]),image:`/scenes/story/story-ashen-leaf-village-65-5.webp`}],[{text:`Scatter the crates into the dark. Burn the wagon and manifest.`,conclusion:`Futures vanish into the treeline in twelve directions, unrecoverable and free. The wagon burns bright behind you, and with it the only paper that proved whose stamp sent them. For one moment the ash falls the wrong way, down through the road dust instead of up into the air. Toma sees it. So do you. Neither of you has paper enough left to prove it.`,trait:`merciful`},{text:`Hide two crates. Let the squad recover the rest, and keep the manifest.`,conclusion:`The squad finds a stalled wagon, a flustered escort, and four crates of six. You keep two crates of futures and the manifest that proves everything. The other four ride on toward the fire, rattling softly, and you make yourself listen until you can't hear them. By dawn Toma has copied out that manifest's worst line three times, each copy worse than the one before, because his hand keeps shaking.`,trait:`suspicious`},{text:`Send Toma into the dark with the crates. Face the squad alone.`,conclusion:`He runs because you told him to, and he doesn't look back, because you told him that too. The lanterns ring you in. The squad captain checks your seal against a list, slowly, and asks you, twice, where your partner went. Behind him the wagon rolls on toward the kiln road, and something inside one crate turns like a small wooden wheel trying to climb water that is not there.`,trait:`loyal`}]),a(`Ashen Leaf Village`,75,`The Ancestors Speak`,`Ancestor-Bound Flame Beast`,`🌿`,[{...i(`Ash on the Wind`,`The kiln yard at dusk, ash falling upward`,`Elder Mori`,[`The Rootfire changed at noon. An hour later, every founder's token turned face-down.`,`The survey wants an exorcist. Hoshina wants the yard closed. I want you.`,`Something is coming up through the fire. It sounds like the founders.`,`Toma went down without us. He thinks they know Aren.`]),image:`/scenes/story/story-ashen-leaf-village-75-6.webp`,choices:[{text:`Go down to the fire.`,nextPage:1}]},{...i(`The First Flame`,`The Rootfire chamber, flames standing upright`,`First Flame Avatar`,[`Stand where we can warm you, little branch. We are trying to be gentle. Gentleness was never fire's gift.`,`We are the founders. The given years, the willing ones. We built the walls you were born behind, and we were glad to burn for them. We are glad still.`,`But for years now, something has been feeding us the other kind. Futures with the stems torn. Futures that scream.`,`We do not digest what is stolen, child. We hoard it, the way a wound hoards heat. Four hundred seasons of stolen mornings are packed inside this fire, and we cannot hold the door shut on them much longer.`,`And hear what we are NOT, so the village hears it from us. We gave our green years to the fire above us. Our ash became walls, medicine, harvests, winter mortar; we knew the price, and we signed it. We never gave to the dark beneath this floor. The stamped slats are not gifts. They are theft wearing orchard language, and theft runs downward. We were built to guard a gift, child. Not to feed a drain.`]),image:`/scenes/story/story-ashen-leaf-village-75-6.webp`,choices:[{text:`Ask what the fire wants from you.`,nextPage:2,trait:`al75-founders-reject-drain`},{text:`Show them the tool outlines you copied from the Reed wall.`,nextPage:3,requireTrait:`al42-filed-a-report`,trait:`al75-founders-reject-drain`}]},{...i(`The Ask`,`The chamber, tokens rising in the heat`,`First Flame Avatar`,[`Not revenge. We are dead. The dead make poor executioners and worse judges.`,`We want a witness. One living voice that can stand in front of the village and say: the founders gave, and the keepers took, and those are not the same fire.`,`It has to be you. The Register cannot read you, so the village cannot quietly cut this truth out of you the way it cuts everything else. Do you understand what a rare pair of shoulders that makes you?`,`But first, there is a duty we cannot do ourselves. Our grief grew a body, years ago. We chained it down here to keep it off the village, and the keeper has been using it as a bellows for her fire ever since. Free it, or end it. But do not leave it hers.`]),image:`/scenes/story/story-ashen-leaf-village-75-6.webp`,choices:[{text:`Follow the chain.`,nextPage:4}]},{...i(`The Ghost Lines`,`The chamber, your copied page held up`,`First Flame Avatar`,[`Hold it higher, child. Yes. A wall of tools that nobody remembers owning, copied in a living hand.`,`You wrote down the dead's own testimony without knowing you were doing it. The boy those tools belonged to is in here with us. The stolen part of him. He still remembers arguing.`,`He asks us to tell his brother something. Tell Toma: the bench was never the whole of me. Tell him about the ink.`,`We would weep, but everything we are is fire. Go to the chain now. What waits there is our grief with its manners burned away, and it deserves better than what she has used it for.`]),image:`/scenes/story/story-ashen-leaf-village-75-6.webp`,choices:[{text:`Follow the chain.`,nextPage:4}]},{...i(`The Bellows`,`The chamber's far vault, a chain thick as a tree`,`Toma Reed`,[`There you are. Don't step on the melted part.`,`The Avatar says this thing is the founders' grief. They chained it down here to protect the village. Hoshina has been using it to feed the fire.`,`It looked at me the way my mother looks at Aren's workbench.`,`We're supposed to free it or kill it. I think it heard that.`]),image:`/scenes/story/story-ashen-leaf-village-75-6.webp`},{...i(`Grief, Off the Chain`,`The vault, the Flame Beast rising`,`Narrator`,[`It rises the size of the fear it was chained for, and it burns in the shape of everyone the fire could not save.`,`The Avatar's voice comes down the flue, steady as a hand on your shoulder: 'Witness it clearly, whatever you choose. Seeing it clearly is the whole work.'`,`The Beast lowers its head toward you. Grief always recognizes its witnesses.`]),image:`/scenes/story/story-ashen-leaf-village-75-6.webp`}],[{text:`Say the founders' words to it: 'given gladly.' Mean them.`,conclusion:`The words land on it like rain on a roof it used to live under. For three heartbeats the Beast is just forty ordinary dead people remembering gladness, and then it fights you the way grieving people fight: to be held, not to win.`,trait:`honorable`},{text:`Shatter the chain. Whatever follows, follows.`,conclusion:`The chain parts with a sound like a hymn ending. Freed grief takes the shortest road toward what hurt it, and the shortest road runs through you. Far above, in her tower, the keeper feels her bellows die.`,trait:`reckless`},{text:`Ask the Avatar what it hasn't told you. Then fight.`,conclusion:`'That the gift was never enough on its own,' it answers at once. 'Two safe winters a generation, and then the cold got its vote back. The keepers used that thinness to excuse the first theft, and they told the living that the dead had agreed to it. We never agreed. We have been trying to say so through the fire ever since.' The truth settles onto your shoulders, and the Beast comes on.`,trait:`suspicious`}]),a(`Ashen Leaf Village`,85,`The Kage Burns the Future`,`Rootbound Elder Champion`,`🌿`,[{...i(`The Detainment Lists`,`The village square, notices in fresh ink`,`Toma Reed`,[`They posted this at dawn. 'Seasonal custodianship of promising branches.' It means detention.`,`Fourteen names. The weaver who petitioned for a school. Jorun's apprentice. Two names from the mill whose only crime is planning a wedding their families forbid.`,`Sena is on it. They took her at breakfast. One of the guards used to bring her scrap iron for her machines.`,`Mori told me why. The more promising the future, the hotter it burns. They're filling the kiln before winter.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`,choices:[{text:`Go to Imera first.`,nextPage:2,trait:`al85-swore-to-imera`},{text:`Go straight to the Kage's orchard office.`,nextPage:3},{text:`Ask Toma why he's stopped calling you 'friend.'`,nextPage:1,requireTrait:`toma-doubt`}]},{...i(`Jonin`,`The square's edge`,`Toma Reed`,[`You noticed. I wondered if you would.`,`You told me to burn Aren's letter. Maybe you thought you were protecting me. I didn't burn it.`,`I'll follow your orders today because fourteen people need help.`,`Afterward, you're coming to my mother's table and telling me why you did it. Then I'll decide whether we're still friends.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`,choices:[{text:`Go to Imera's house.`,nextPage:2}]},{...i(`Imera's Kitchen`,`The house behind the eleven-flower fence`,`Imera`,[`Don't tell me you're sorry. I can't do anything with sorry right now.`,`You hid a flower for us once. I haven't forgotten. So I'll tell you what I can't tell the survey office.`,`They let me visit her yesterday. She's warm and well fed. They give her puzzles and write down how she solves them. She thinks she's been chosen for something good.`,`Her first loom is under the bed. Bring her home before they make her forget why she built it.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`,choices:[{text:`Go to the orchard office.`,nextPage:3}]},{...i(`The Orchard Office`,`The Kage's office, rain on new grafts`,`Kage Hoshina Enju`,[`You've seen the list. Sit down.`,`The split-oak winter killed forty one people. The granary winter killed twenty six. Most were children.`,`No child has frozen here in thirty years. I chose fourteen people to keep it that way.`,`I know why you're angry. Anger is not a winter plan.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`,choices:[{text:`"Fourteen people are not firewood."`,nextPage:4},{text:`Show her your own scarred line. Make it personal.`,nextPage:5,requireTrait:`al70-claimed-the-name`},{text:`Ask her exactly what the fire does with the unwilling.`,nextPage:6}]},{...i(`Not Firewood`,`The orchard office`,`Kage Hoshina Enju`,[`Don't use that word in my office. I know their names.`,`Sena is nine. She builds little machines that walk. I have three of them upstairs.`,`You can call me a monster after you've found another way to keep four hundred people alive.`,`The burning is at frost-fall. Bring me a real alternative before then and all fourteen go home. Otherwise, stay out of my way.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`,choices:[{text:`Leave her office.`,nextPage:7}]},{...i(`The Scarred Line`,`The orchard office`,`Kage Hoshina Enju`,[`I've read your page many times.`,`Someone cut you before you came here. No stamp, no date, no record of what they took.`,`That is not proof that every cut is wrong. It is proof that an unchecked person with the shears is dangerous.`,`Frost-fall is three days away. Bring me another way to heat the village.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`,choices:[{text:`Leave her office.`,nextPage:7}]},{...i(`The Unwilling`,`The orchard office`,`Kage Hoshina Enju`,[`You already know the answer. An unwilling future burns longer. A child's burns longer still.`,`The founders' gifts could only carry us through two winters in a generation. That was not enough.`,`The village doesn't keep all the heat. Part of it goes through a lower draw marked with a quartered circle. The name on the old agreement is Hollow Gate.`,`I inherited that agreement, and I renew it every winter. You can decide what that makes me after frost-fall. Until then, bring me a better winter.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`,choices:[{text:`Leave her office.`,nextPage:7,trait:`al85-hoshina-named-gate`}]},{...i(`The Detention Rows`,`Outside the rows, the Elder Champion at the gate`,`Narrator`,[`The Rootbound Elder Champion stands at the detention gate. It has guarded the elders' orders for so long that bark has grown over its armor.`,`Through the fence, a small girl waves at you cheerfully and holds up a finished puzzle for you to admire.`,`Frost is three days out. The kiln flue is already warming. And under Toma's coat, held like a heartbeat, is a small wooden loom that knows how to play dead.`]),image:`/scenes/story/story-ashen-leaf-village-85-7.webp`}],[{text:`Break the rows open tonight. All fourteen, into the dark.`,conclusion:`Fourteen futures scatter into the treeline before the alarm bell finds its voice. The transfer depot burns behind you, and with it the only manifest that carried her seal. By morning she is calling it a kidnapping, and half the cold village believes her.`,trait:`merciful`},{text:`Challenge the Champion at the gate, in daylight, before everyone.`,conclusion:`The square fills fast. Whatever happens next will have three hundred witnesses, which is the entire point, and no second plan, which is also, somehow, the point. Deep in its bark, the old Champion creaks into something like a smile.`,trait:`reckless`},{text:`Let the transfer start, and shadow the crates to her private room.`,conclusion:`Two detainees ride the first wagon while you follow in the dark, and every step of not acting costs you something you will pay for later, in dreams. But by midnight you know where the wonder room is. Sena's machines are in it. So is your page.`,trait:`suspicious`}]),a(`Ashen Leaf Village`,100,`The Tree Must Choose`,`Kage Hoshina Enju, First Flame Vessel`,`🌿`,[{...i(`Frost-Fall`,`The Register hall, every line glowing faint`,`Narrator`,[`Frost-fall, and the Register wall is lit from inside, forty strides of lives glowing like banked coals. The hall is empty. She sent everyone home warm.`,`Your black flower has grown all season. Tonight its petals are fully open, and for the first time, the whole bloom is leaning in one clear direction: toward the kiln stair.`,`The stair door stands unlocked. On the top step sits a plate of honey bread, still warm, and a note in a keeper's steady hand: 'You were always going to come tonight. Eat something first.'`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`},{...i(`At the Stair`,`The kiln stair door`,`Toma Reed`,[`I know you have to go down alone. I don't like it.`,`Take Aren's letter. If she lies about him, read it to her.`,`Come to my mother's house afterward. There will be tea.`,`Go. I'll keep the door open.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`Go down alone.`,nextPage:2}]},{...i(`The Keeper at the Fire`,`The Rootfire chamber, racks emptied, shears on an anvil`,`Kage Hoshina Enju`,[`You're here.`,`Those are the shears. I took them out to clean them this morning. Six hours later, I was still holding them.`,`I made my first cut at thirty one. A boy planned to redirect the flood, and his bridge would have drowned the low fields.`,`Don't ask whether I regret it. That isn't a useful question tonight.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`},{...i(`The Vessel`,`The fire climbing her arms like ivy`,`Kage Hoshina Enju`,[`The fire started answering me in the spring. Now it comes whether I call it or not.`,`I hear the people I cut. The bridge boy when it rains. The weaver teaching a school that never existed.`,`Maybe those are their memories. Maybe they're mine. I don't know anymore.`,`Ask what you came to ask.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`The fire is not one fire.`,nextPage:4}]},{...i(`The Lower Draw`,`The Rootfire behind her: an upper flame, cedar-gold, and beneath the grate a darker pull`,`Kage Hoshina Enju`,[`Look under the grate. The dark pull beneath the flame is the lower draw.`,`The Rootfire keeps enough to warm Ashen Leaf. The rest goes to Hollow Gate.`,`I told myself it was a tax. That every Kage paid one and at least our share kept children alive.`,`Aren Reed fed both fires. I approved it. Now show me what you brought.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`Face her across the anvil.`,nextPage:20,trait:`al100-lower-draw-confessed`}]},{...i(`The Better Winter`,`The anvil, water dripping from your sleeve`,`Kage Hoshina Enju`,[`Show me. Slowly.`,`Aren Reed's water-screw. Jorun built the housing, didn't he?`,`How long has the full-size one been running? How many people does it feed?`,`One channel is not a winter plan. Give me the numbers.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`"Ninety mouths from the terraces alone. And the terrace families watched the water climb."`,nextPage:6,requireTrait:`al88-proved-the-winter`},{text:`Open Mori's book to the measured pages and read her every line.`,nextPage:7,requireTrait:`al88-held-the-proof`},{text:`"Your own survey filed the proof. You have already read it three times."`,nextPage:8,requireTrait:`al88-baited-the-survey`},{text:`Set Aren's model on her anvil and let the water speak for itself.`,nextPage:9}]},{...i(`What the Village Saw`,`The anvil, her hands very still`,`Kage Hoshina Enju`,[`Ninety people from the terraces alone?`,`And the families saw the channel running. They know where the water came from.`,`Then I can't call it a failed test and make it disappear. Not anymore.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`She looks at the shears.`,nextPage:16}]},{...i(`The Measured Pages`,`Mori's book open on the anvil`,`Kage Hoshina Enju`,[`Give me the book.`,`This flow rate is too high. No. Wait. I read the column wrong.`,`Worst week, ninety people. Mori signed every page.`,`How long has this been running?`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`She closes the book.`,nextPage:16}]},{...i(`Her Own Eyes`,`A survey report unfolded between you`,`Kage Hoshina Enju`,[`I read this report three times. I thought the east fields were wet because a test line had broken.`,`You let my survey find it before you told me.`,`Do you have any idea what could have happened if that channel failed?`,`No. Don't answer. It didn't fail. That's the point.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`She folds the report closed.`,nextPage:16}]},{...i(`The Water Answers`,`The model turning in a channel of firelight`,`Kage Hoshina Enju`,[`The vane is still cracked.`,`I tested the full design once, at night, in this room. It worked then too.`,`Now the full screw is running upstairs without burning anyone's future.`,`I knew it could work.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`She watches the water climb.`,nextPage:16}]},{...i(`This Part Is Ours`,`The kiln stair door opening behind you; Toma and Sera come down into the firelight`,`Toma Reed`,[`Thank you for keeping the door open, %name. We need to do this part.`,`That's Aren's model. You signed the order that took this work from him.`,`I had a speech. I can't remember it. Mom?`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`Let Sera speak.`,nextPage:11}]},{...i(`Handwriting`,`The chamber, Sera laying the letter flat on the anvil`,`Sera Reed`,[`My son wrote this. I know that now. I know the threes he never closed. I know how he pressed too hard on the page when he was angry, and he was angry so much of the time.`,`For twenty years, I thought he had always been quiet. That wasn't my son. You left me with someone easier to remember.`,`His channel feeds ninety people.`,`And my son was not a bench.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`The Kage looks at the letter.`,nextPage:12}]},{...i(`A Mother's Proof`,`The Rootfire dimming, Hoshina very still`,`Kage Hoshina Enju`,[`I remember Aren. He argued with me for an hour.`,`I should have told you that. I should have told you the machine worked.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`She cannot look away from the letter.`,nextPage:16}]},{...i(`Water Without a Name`,`The channel numbers chalked on a slate`,`Kage Hoshina Enju`,[`The number is real. I can see the east field from my tower.`,`But you haven't shown me whose design this is or who paid for it.`,`I won't rebuild the village around a machine with no history and no one responsible for it.`,`You brought me water. You didn't bring me the rest.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`She sets the slate down.`,nextPage:20}]},{...i(`The Unfinished Answer`,`Aren's model in her scarred hands`,`Kage Hoshina Enju`,[`Aren Reed's model. I signed the cut.`,`I tested it. It worked.`,`The full screw is running upstairs, but you kept Aren's page in your own kit. His family still doesn't have it.`,`You want to accuse me of deciding what belongs to other people? Give the page back first.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`She sets the model down gently.`,nextPage:20}]},{...i(`Mori Reads the Pattern`,`Mori opening the bloom charts on the anvil beside the shears; Hoshina says his name once, quietly`,`Elder Mori`,[`No. Let me do this.`,`These are forty years of bloom charts and surveys. I knew the pattern. I kept telling myself I needed more proof.`,`I was afraid, Hoshina. That's the reason.`,`The flowers marked the people you planned to take. I helped you call it a blessing.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`He sets the charts beside the shears.`,nextPage:20}]},{...i(`No Answer Left`,`The Rootfire low, Hoshina looking at the shears on the anvil`,`Kage Hoshina Enju`,[`I built my life around one answer. You proved it was not the only one.`,`Now we find out whether I can let it go.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`Enough. The tree chooses now.`,nextPage:20}]},{...i(`Answer for Mori's charts. You've known the pattern for years.`,`The reckoning`,`Kage Hoshina Enju`,[`Mori showed you how to read the blooms. Then you knew which families were in danger and still had to walk past their houses.`,`Did you ever hope a flower would die before the survey found it? I did. More than once.`,`You carried that knowledge for one season. I carried it for thirty years and kept approving the cuts. Don't confuse understanding me with forgiving me.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`Enough. The tree chooses now.`,nextPage:20}]},{...i(`Answer for my page. You kept my cut in your wonder room.`,`The reckoning`,`Kage Hoshina Enju`,[`Yes. Your stub is in that room. It's older than every cut I made, and I don't know who put it there.`,`I couldn't burn it. I also didn't return it. Then you found it and demanded an answer I didn't have.`,`If you survive this, find the person who cut you. Don't let them hide behind numbers the way I did.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`Enough. The tree chooses now.`,nextPage:20}]},{...i(`Answer for Aren Reed. His future gets finished.`,`The reckoning`,`Kage Hoshina Enju`,[`I signed Aren Reed's cut. Don't look at Mori. The approval was mine, and I had read the complaint.`,`I built his screw in this room afterward. It worked. Ninety more mouths from the east terraces. I counted them myself.`,`Then I worked out what it would cost the Rootfire. I chose the fire and destroyed his work. Tell Toma I knew exactly what I was burning.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,choices:[{text:`Enough. The tree chooses now.`,nextPage:20}]},{...i(`The Shears on the Anvil`,`The Rootfire at full roar, Hoshina alight`,`Kage Hoshina Enju`,[`Enough. I've heard you.`,`I've held these shears for thirty years. I don't know how to put them down, and I still don't trust anyone else to get this village through winter.`,`If you want them, take them from me.`,`Show me what replaces this.`]),image:`/scenes/story/story-ashen-leaf-village-100-8.webp`,leftName:`Player`,rightName:`Kage Hoshina Enju`,rightImage:`/portraits/kage-hoshina-enju-hollow.webp`,choices:[{text:`Show her the better winter.`,nextPage:5,requireTrait:`al88-better-winter-carried`},{text:`Let the Reeds show her the better winter.`,nextPage:10,requireTrait:`al88-better-winter-deferred`},{text:`Let Mori answer for his charts.`,nextPage:15,requireTrait:`al92-mori-present`},{text:`Show her Aren's model.`,nextPage:14,requireTrait:`al88-unfinished-answer`,forbidTrait:`al88-better-winter-ready`},{text:`Show her the east channel numbers.`,nextPage:13,requireTrait:`al88-water-proven`,forbidTrait:`al65-saved-the-screw`},{text:`Answer for Mori's charts. You've known the pattern for years.`,nextPage:17,requireTrait:`al58-took-the-knowledge`},{text:`Answer for my page. You kept my cut in your wonder room.`,nextPage:18,requireTrait:`al70-claimed-the-name`},{text:`Answer for Aren Reed. His future gets finished.`,nextPage:19,requireTrait:`al88-reed-proof-any`}]}],[{text:`Break the shears on the anvil. Give every future back.`,conclusion:`The shears break on the anvil. Upstairs, cedar walls groan as stolen futures return to the people they were cut from. Beneath the kiln, the lower pipe empties and the seam under the fire goes cold. The Rootfire draws nothing downward. Winter will be hard, but it will belong to the people living through it. Hoshina touches the broken blade once, then the fire takes her and she attacks.`,trait:`honorable`},{text:`Bind the Rootfire to willing gifts alone. Sheathe the shears forever.`,conclusion:`The fire shrinks to the founders' flame. Every unsigned stamp splits, and from tonight the Rootfire accepts only willing adult signatures. The lower seam opens, finds nothing it is allowed to take, and closes. Ashen Leaf will have to ask for its warmth now, winter by winter. Hoshina bows to the new rule. The fire in her does not.`,trait:`merciful`},{text:`Take the shears. The village needs a keeper who was never fooled.`,conclusion:`The grips are warm, and they fit your hand exactly, and you understand all at once why: the Register has been growing you toward this room since the day it bloomed. Below the fire, the dark seam does not close. It waits, warmer by a single degree, for your first approval. Hoshina smiles like winter finally breaking. 'Then prove it,' says the fire, with her mouth.`,trait:`ambitious`}])],"Frostfang Village":[a(`Frostfang Village`,4,`The Pack Survives`,`Snow Warden Pup`,`❄`,[{...i(`First Bell`,`The training yard at first bell, breath-fog in rows, lantern lines overhead`,`Captain Yura`,[`New intake. Stand on the worn spots; they're worn for a reason.`,`I'm Captain Yura. You'll freeze in that coat. After drill, requisition a real one and tell them I sent you; the clerk owes me.`,`At every bell, you answer your name. Listen for the person beside you. If they don't answer, you tell me. You don't assume somebody else noticed.`,`Sova keeps the book. She'll explain the Count.`,`Move. Your feet are getting cold.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`},{...i(`The Intake`,`The roll stone, Elder Sova with the Count book open`,`Elder Sova`,[`Wrist here. If you feel faint, sit down. The brazier is behind you.`,`The words are: checked, counted, kept, warm. Checked means the plate knows you. Counted means you're in this book. Kept means we search if you go missing. Warm means we bring you home.`,`That's all. Now tell me why you want your name in the Count.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`,choices:[{text:`"So the cold takes nobody on my watch."`,nextPage:2,trait:`ff4-count-protector`},{text:`"To be the strongest back in the pack."`,nextPage:3,trait:`ff4-count-strongest`},{text:`"Someone came for me once. I'm repaying it."`,nextPage:4,trait:`ff4-count-repayer`},{text:`"I'm looking for someone who walked away."`,nextPage:5,trait:`ff4-count-seeker`},{text:`"I don't know yet."`,nextPage:6,trait:`ff4-count-unknown`}]},{...i(`A Guard's Reason`,`The roll stone`,`Elder Sova`,[`So the cold takes nobody on your watch. Good.`,`You're in the book, %name.`,`Remember you said that when the watch gets difficult.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`,choices:[{text:`Step to the mark plate.`,nextPage:7}]},{...i(`A Strong Back`,`The roll stone`,`Elder Sova`,[`The strongest back in the pack. We can use one.`,`You're in the book, %name.`,`Don't try to carry a whole patrol by yourself. I've seen people ruin their knees that way.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`,choices:[{text:`Step to the mark plate.`,nextPage:7}]},{...i(`A Debt to Pay`,`The roll stone`,`Elder Sova`,[`Someone came for you, so you'll come for someone else. I understand.`,`You're in the book, %name.`,`Just remember that you don't owe the Count your whole life.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`,choices:[{text:`Step to the mark plate.`,nextPage:7}]},{...i(`A Door That Closed`,`The roll stone`,`Elder Sova`,[`You're looking for someone who left. People don't often admit that here.`,`You're in the book, %name.`,`I hope you find them. Ask why before you ask them to come back.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`,choices:[{text:`Step to the mark plate.`,nextPage:7}]},{...i(`A Blank Line`,`The roll stone`,`Elder Sova`,[`You don't know yet. That's allowed.`,`You're in the book, %name. I left the reason blank.`,`Come back if you want to add one later.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`,choices:[{text:`Step to the mark plate.`,nextPage:7}]},{...i(`The Fogged Plate`,`The gate's mark plate, frost crawling where a wrist should read`,`Captain Yura`,[`Wrist on the plate. It reads you, it logs you into the Count, and that's the whole ceremony.`,`Huh. Wipe it and try again.`,`Stop. Look. It isn't misreading you. It's reading somebody. That's a name coming up, and it's an OLD name. Nobody's had a plate-read like that in twenty years.`,`Sova. SOVA. The plate just read the new intake as someone long gone. Bring the book.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`},{...i(`Someone Long Gone`,`The gate, Sova's thumb on the fogged plate`,`Elder Sova`,[`I haven't seen that before.`,`It may be frost in the plate. These things are old.`,`But the plate doesn't read skin. It reads the name a wrist answers to, and yours answered with the name of someone who died years ago.`,`I'll check the old books. For now, Yura is waiting in the yard.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`,choices:[{text:`Form up in the yard.`,nextPage:9}]},{...i(`The Loose Warden`,`The yard, a Snow Warden Pup pacing the drill square, six recruits in line`,`Captain Yura`,[`Listen up. The pup has broken out of the pens twice this month. It's young, it's frightened, and it is still two hundred pounds of teeth.`,`The drill is simple. The formation holds, the newest takes point, and the pack backs the point. That isn't hazing. It's how we learn what your spine does when it counts.`,`Nobody fights alone in Frostfang. But somebody always fights FIRST.`,`Point position, intake. The bell is yours.`]),image:`/scenes/story/story-frostfang-village-4-0.webp`}],[{text:`Hold formation. Trust the line at your back.`,conclusion:`You take point and stay exactly where the pack can use you, and six strangers become a wall behind your shoulders. The pup breaks against the formation like weather. Yura says nothing, but she marks something in the drill book, and the something has your name on it.`,trait:`loyal`},{text:`Break formation. Take the pup down before it reaches the line.`,conclusion:`You leave the line while Yura is still shouting the hold order, and you meet the pup alone in the open square. It goes down. So does the drill. Half the yard is furious and the other half can't stop looking at you, and neither half forgets.`,trait:`reckless`},{text:`Watch its paws. Herd it toward the open pen instead.`,conclusion:`You read the animal instead of fighting it: it isn't attacking, it's cornered. Two feints and a held gate later, the pup pens itself, panting, unbled. Yura calls the drill void and buys you soup anyway. 'Wrong orders, right call,' she says. 'That combination gets complicated here. You'll see.'`,trait:`suspicious`}]),a(`Frostfang Village`,15,`The Missing Patrol`,`Oathbound Soldier`,`❄`,[{...i(`Five Names Unanswered`,`The roll stone at third bell, snow starting, five names hanging`,`Captain Yura`,[`Ruven's patrol missed roll call. Five people. Their ridge camp is empty, but the fires were banked and their packs are still there.`,`Kael called it desertion and struck their names from the Count.`,`Ruven wouldn't leave his dog, and he wouldn't abandon a clean kit. Something happened to them.`,`I'm going north. Are you coming?`]),image:`/scenes/story/story-frostfang-village-15-1.webp`},{...i(`The Kage in the Snow`,`The north gate, Kael Whitefang walking IN out of the storm carrying a shepherd`,`Kage Kael Whitefang`,[`Gate. Open. Now.`,`This shepherd strayed past his line in the east folds. He's frostbit, not dead. Get him soup and a warm wall. Move.`,`You're going north. No.`,`A person stays in the Count if the mark answers, the route is logged, and the rescue line holds. This shepherd still met two of those conditions, so I went for him.`,`Ruven's patrol met none of them. Their names were struck.`,`You think they're lost. I think they deserted. Either way, I'm not sending more people into that storm.`]),image:`/scenes/story/story-frostfang-village-15-1.webp`},{...i(`What Yura Knows`,`The north road, snow thickening`,`Captain Yura`,[`Kael has carried people home through weather that should have killed him.`,`But once the Count strikes a name, he stops seeing the person. I've never understood how both can be true.`,`Ruven banked his fire. He meant to return.`,`Tracks ahead. One person, coming toward us. Something is wrong with the way he's walking.`]),image:`/scenes/story/story-frostfang-village-15-1.webp`},{...i(`Dain Comes Back`,`The road, a soldier walking out of the white with his hood down`,`Frost Seal Echo`,[`The soldier Dain is returned to the Count.`,`The soldier Dain reports: the patrol went beyond its line. The patrol is corrected. The Count is whole.`,`You stand outside your posted rotation. State your numbers. The Count is whole. The Count is whole.`,`Cold is only warmth that stopped asking questions. Return to the wall.`]),image:`/scenes/story/story-frostfang-village-15-1.webp`},{...i(`The Corrected Man`,`The road, Dain's hood down, frost in a script down his wrist`,`Captain Yura`,[`That's Dain, but he doesn't sound like himself. He stammers when he's afraid. He hums. He's doing neither.`,`The script on his arm isn't ours. It goes all the way to his elbow.`,`The other four are still out there.`,`Don't forget this is Dain's body. Put him down without killing him if you can.`]),image:`/scenes/story/story-frostfang-village-15-1.webp`}],[{text:`Take the corrected man down fast, before it learns you're a threat.`,conclusion:`You hit first and hard, and the thing wearing Dain fights with drill-perfect, joyless precision until it can't. He goes down breathing. Under the deep script his own mark is still there, faint, like handwriting under a stamp. Yura splints his arm with hands that don't shake until after.`,trait:`reckless`},{text:`Stand between it and the village. Nothing corrected passes.`,conclusion:`You plant yourself on the road and make the correction come through you, and it does, methodically, reciting the Count. You hold. When it finally stops moving, the road behind you is still clean snow, and Yura looks at you the way soldiers look at load-bearing walls.`,trait:`honorable`},{text:`Match its cadence. Answer its numbers. Learn the script's grammar.`,conclusion:`You give the Echo's questions back in its own flat rhythm, numbers for numbers, and for eleven exchanges the thing believes you might be a colleague. Eleven exchanges of grammar, memorized. When it finally lunges, you already know how corrected things decide, which will matter more than anyone on this road yet knows.`,trait:`suspicious`}]),a(`Frostfang Village`,25,`The Loyalty Seal`,`Frost Seal Guardian`,`❄`,[{...i(`Cut From the Ice`,`A ravine north of the line, three figures standing in cut ice like specimens`,`Captain Yura`,[`There. Snow take me. There they are.`,`They're standing up. In the ice. Like they walked into it and it agreed with them.`,`That's Ruven. Front. Cut them out slow; frostbite by inches is survivable, panic isn't.`,`Three. Count again. THREE. We met Dain on the road, so that's four of the five accounted for. But Kessa isn't here. She's the fifth name, the youngest of them, and she is not here.`]),image:`/scenes/story/story-frostfang-village-25-2.webp`},{...i(`The Deep Script`,`The ravine, three soldiers thawing, wrists black with script to the elbow`,`Narrator`,[`They wake calm. That is the wrong part. Men cut from ice should shake, weep, swear. These three stand up, form a line, and wait for orders.`,`Ruven looks at Yura with polite, total certainty. He asks nothing about his wife. He asks nothing about his dog. He asks for his rotation.`,`The script runs wrist to elbow on all three. Force-sealed. An oath they never spoke, written in past the asking.`,`The Count is whole, they say, all three, in unison, and the ravine's cold has nothing on the sound of it.`]),image:`/scenes/story/story-frostfang-village-25-2.webp`},{...i(`The Seal's Voice`,`The ravine mouth, the Frost Seal Echo standing on the ice, guardian shapes forming under it`,`Frost Seal Echo`,[`Four are recovered. The Count is whole.`,`The fifth resisted correction. The fifth is pending.`,`You transport recovered assets. This is approved. You inquire after the pending. This is not approved.`,`Warmth is owed to the counted. The counted are kept. You are keeping poorly. Stand down.`]),image:`/scenes/story/story-frostfang-village-25-2.webp`,choices:[{text:`"You read her license once. Read this thing its own terms."`,nextPage:3,requireTrait:`ff20-read-her-license`},{text:`Put the three behind you and face the Guardian.`,nextPage:4}]},{...i(`Terms of Service`,`The ravine mouth, the Echo's cadence stuttering`,`Captain Yura`,[`Harrow was right. It follows the wording.`,`Kessa was checked at intake. The checked are counted, and the counted are kept. Your own rule says she's owed a search.`,`It's hesitating.`,`Move. The ice is coming up.`]),image:`/scenes/story/story-frostfang-village-25-2.webp`,choices:[{text:`The ice stands up.`,nextPage:4}]},{...i(`The Frost Seal Guardian`,`The ravine, a guardian of old ice rising between you and the road home`,`Captain Yura`,[`That's an old Guardian. The seal is controlling it the way it controlled Dain.`,`We have three people behind us and Kessa is still missing.`,`The three come home. That's the mission. I'll keep looking for Kessa after that.`,`Your call.`]),image:`/scenes/story/story-frostfang-village-25-2.webp`}],[{text:`Hold the road until all three are clear, then break contact clean.`,conclusion:`You fight a wall of winter to a standstill exactly as long as the rescue needs, and not one breath longer, and then you fold back through the ravine like a drill answer. Three men come home. The Guardian watches you leave with something like professional respect, if ice can respect a schedule.`,trait:`honorable`},{text:`Study the script while you fight. The seal writes; writing has rules.`,conclusion:`Every strike you trade, you're reading: the Guardian moves in the litany's own meter, four beats and a hold. By the end you can feel the next line before it lands. Yura hauls you out bleeding and furious with you, and you come home carrying the seal's grammar like a stolen map.`,trait:`suspicious`},{text:`Go through it. Kessa is out there and this thing is the door.`,conclusion:`You don't fight the Guardian; you BREACH it, straight through the old ice with everything you own, because a girl is pending on the far side. It costs you skin and it doesn't find her, but the seal learns something new about the shape of you, and files it, and starts, in its cold way, to plan.`,trait:`reckless`}]),a(`Frostfang Village`,35,`The Pale Pack`,`Oathbound Ice Captain`,`❄`,[{...i(`The Struck Names`,`A rebel cavern in the glacier, forty-one people, no marks, warm fires`,`Pale Pack Runner`,[`Weapons stay at the mouth. That's not a threat, it's furniture; we've no racks for them inside.`,`Welcome to the Pale Pack. Forty-one names the Count struck. Deserters, doubters, one woman who missed a check nursing her sick mother. Struck all the same.`,`Look around, but don't romanticize it. We call the Roll here because we choose to, not because a mark makes us. Some nights people answer angry. Some nights a name doesn't come until the third call. The fires are warm and they smoke; the stew is thin. Two winters ago we lost a boy because the east watch slept through second bell.`,`The youngest of us is Kessa, off the ridge patrol. She walked in half-frozen a week after the seal took her squad, unsealed, still marked 'pending' in the wall's book. She teaches the children knots now.`,`So no, we are not proof that walking free is easy. We are proof of one thing only: the Count lied when it told you there was no other way. Ask the wall how their Count is doing.`]),image:`/scenes/story/story-frostfang-village-35-3.webp`},{...i(`Yura's Roster-Mate`,`The cavern fires, a big woman standing up slow`,`Captain Yura`,[`Kessa is here? She's alive?`,`Marrin.`,`I filed the report that struck your name. The handwriting is mine. I'm not asking you to forgive me.`,`You built another Roll out here without the Count.`,`I don't know what to say.`]),image:`/scenes/story/story-frostfang-village-35-3.webp`},{...i(`Returned to the Count`,`The cavern mouth, torchlight, a sealed recovery detail forming up outside`,`Narrator`,[`The recovery detail arrives at dusk: twelve sealed soldiers and a captain whose wrist script is old and deep, a man who was himself recovered once, and speaks of it the way saved men speak of medicine.`,`The order he carries is short, in Kael's own hand: ALL STRUCK NAMES RETURNED TO THE COUNT. RECOVERY AUTHORIZED. SEALING AUTHORIZED.`,`Forty-one people wait in the cavern behind you. Twelve sealed soldiers stand on the ice in front. The mountain does not care either way.`,`The captain gives you, formally, one bell to bring them out willing. He says the word willing without any sign it means something.`]),image:`/scenes/story/story-frostfang-village-35-3.webp`,choices:[{text:`Ask Yura, quietly, what she's about to do.`,nextPage:3,requireTrait:`yura-trust`},{text:`Answer the captain at the mouth.`,nextPage:4}]},{...i(`The Captain's Arithmetic`,`The cavern mouth's shadow, Yura checking her gear by touch`,`Captain Yura`,[`My mark says I stand with the recovery detail.`,`Marrin is behind us. Kael signed the order that sent those soldiers here.`,`If this goes wrong, I'm staying in the entrance. I'm not letting them take the cavern.`,`Whatever you decide, say it loudly enough for both sides to hear.`]),image:`/scenes/story/story-frostfang-village-35-3.webp`,choices:[{text:`Answer the captain.`,nextPage:4}]},{...i(`One Bell`,`The cavern mouth, the detail in formation, snow beginning`,`Pale Pack Runner`,[`They've done this before, you know. Not here. Smaller camps. Struck names, recovered, and you meet them a season later at the wall with script to the elbow, asking for their rotation.`,`Forty-one of us. Some will fight. Some are children. Some would honestly rather be sealed than spend another winter unforgiven; don't judge them, warmth is warmth when you're tired enough.`,`The bell the captain gave you is almost out.`,`So, wall-walker. What ARE you, out here past the Count?`]),image:`/scenes/story/story-frostfang-village-35-3.webp`}],[{text:`Stand in the mouth beside Yura. The cavern doesn't empty tonight.`,conclusion:`Two of you in the mouth, then Marrin makes three, then the runner makes four, and the sealed captain recalculates a doorway that has grown teeth. Recovery withdraws, formally, pending reinforcement. The Pale Pack's fires burn all night, and forty-one names answer the midnight Roll like a hymn.`,trait:`honorable`},{text:`Negotiate: the children and the willing go down warm, the rest stay free.`,conclusion:`You split the impossible order into human pieces: nine go down the mountain fed and blanketed, by their own word, and thirty-two remain, and you sign the difference in your own name as ranking witness. The captain files it, because it is, technically, a recovery. Kael will read what you signed by morning, and know exactly what it says about you.`,trait:`merciful`},{text:`Let the bell run out. Then shadow the detail's captain home.`,conclusion:`You give the captain his formal refusal at the mouth, let recovery withdraw empty-handed, and then you follow the sealed unit down the mountain, off their flank, all night. They don't go to the barracks. They go to a door in the glacier's foot that no map holds, and file in like heat returning to a stove. You mark it. The seal-house has an address now, and only you have it.`,trait:`suspicious`}]),a(`Frostfang Village`,50,`Jonin of the Frozen Oath`,`Jonin Rank Trial: Glacier Twins`,`❄`,[{...i(`Both or Neither`,`The oath hall, a two-page scroll flat on the stone table`,`Elder Sova`,[`Read before you sign. Both pages. I'll wait; I've grown good at waiting.`,`Page one is your rank: Jonin of Frostfang. You earned it, and the book agrees.`,`Page two is the officer's mark: deep script, wrist to elbow. That's not the recruit's mark. That's the one that binds.`,`One signature covers both pages. Both or neither. That rule is mine, and I have never been prouder or more ashamed of a rule.`]),image:`/scenes/story/story-frostfang-village-50-4.webp`},{...i(`The Oath Is a Comfort`,`The oath hall, Kael by the brazier, hands out to the heat`,`Kage Kael Whitefang`,[`You should hesitate. This mark does not come off.`,`On a ridge at night, it means someone knows where you are and someone comes for you. I know what that is worth.`,`People talk about choice when they're warm. I use this mark to keep them alive.`,`Sign or don't. If you refuse it, the Count will not send a rescue for you.`]),image:`/scenes/story/story-frostfang-village-50-4.webp`,choices:[{text:`"Essen's doubt walked out of him at the gate. I held it. Ask me what it weighed."`,nextPage:2,requireTrait:`ff42-held-the-doubt`},{text:`Take up the pen.`,nextPage:3}]},{...i(`What Doubt Weighs`,`The oath hall, the brazier crackling`,`Kage Kael Whitefang`,[`You held a man's doubt. And?`,`I've held a frozen child. That weighs more to me.`,`The gate took Essen's grievance without permission. I know. I have not dealt with it because the winter keeps coming first.`,`Maybe you think that's an excuse. Fine. Sign or don't.`]),image:`/scenes/story/story-frostfang-village-50-4.webp`,choices:[{text:`Take up the pen.`,nextPage:3}]},{...i(`The Pen Gets Lighter`,`The hall's side door, Yura turning her own wrist in the brazier light`,`Captain Yura`,[`Before you decide, look at my wrist.`,`I signed at nineteen and signed again with every promotion. My hand shook the first time. The last time, I was talking about boots and barely looked down.`,`The mark makes it easy to stop asking what you're agreeing to.`,`Read both pages. Take your time.`]),image:`/scenes/story/story-frostfang-village-50-4.webp`,choices:[{text:`The Glacier Twins wait.`,nextPage:4}]},{...i(`The Rank Trial`,`The proving floor, two glacier-pale duelists bowing as one`,`Elder Sova`,[`The trial stands regardless. Rank is proven, not signed.`,`The Glacier Twins. Sealed young, sealed deep, and the finest formation fighters the mark ever made. They move like one soul in two coats. That's the sales pitch, you understand. Look at what the mark builds. Look what you could be.`,`The book and I will be watching what you are instead.`,`Begin when the bell says. And child... whatever your page says afterward, come eat. Rank tastes better with soup.`]),image:`/scenes/story/story-frostfang-village-50-4.webp`}],[{text:`Take rank with the recruit's mark only. Refuse the deep script, out loud.`,conclusion:`You sign page one and set the pen down in front of the Kage, the Elder, and the book. An unbound Jonin: the first in living memory. Kael says nothing, which everyone in the hall knows is his loudest register. Sova enters it with a hand that is absolutely not steady, and looks twenty years younger doing it.`,trait:`honorable`},{text:`Sign both pages. Rank now, and the binding's secrets from inside it.`,conclusion:`The deep script takes like ice taking a lake: total, quiet, certain. And you learn on the first night what no refuser ever learns: the mark WHISPERS. Rotations, tallies, the warmth of the vault, faint and constant, a lullaby with a ledger in it. You wanted to know the machine. Now the machine assumes you're a part.`,trait:`ambitious`},{text:`Ask Sova, at the table, why the litany never mentions leaving.`,conclusion:`The hall goes drill-quiet. Checked, counted, kept, warm; four verbs, and not one of them is 'released.' Sova looks at the litany she has recited for forty years like a door she has never once tried the handle of. 'Sign or step back,' Kael says, flat. You step back, and the question stays in the hall like woodsmoke, and outlives the ceremony.`,trait:`suspicious`}]),a(`Frostfang Village`,65,`Orders in White Blood`,`Oathbound Purge Unit`,`❄`,[{...i(`The Removal Order`,`The muster yard before dawn, an order pinned under a lamp`,`Captain Yura`,[`Read this.`,`The order says there are nineteen Pale Pack fighters in the old quarry. I'm assigned the sweep, and you're the ranking witness.`,`I pulled the original scout report. It lists nine children, six elders, and four unsealed adults. No fighters.`,`Someone changed 'people' to 'fighters' before Kael signed it.`]),image:`/scenes/story/story-frostfang-village-65-5.webp`,choices:[{text:`"You stayed in the Count to fix it from inside. Is this the day that pays off?"`,nextPage:1,requireTrait:`ff58-stayed-in-the-count`},{text:`Ride for the quarry ahead of the unit.`,nextPage:2}]},{...i(`From Inside`,`The muster yard, Yura buckling her kit slow`,`Captain Yura`,[`I said I stayed so I could change things from inside.`,`Here's what that bought me: I can delay the unit for two hours under confirmation protocol. It's legal, and it has my signature.`,`Twelve years for two hours. I thought it would be more.`,`Use them.`]),image:`/scenes/story/story-frostfang-village-65-5.webp`,choices:[{text:`Ride. Now.`,nextPage:2}]},{...i(`The Old Quarry`,`The quarry floor, tents against the cut walls, children's snow-forts by the pool`,`Pale Pack Runner`,[`You rode hard. What's behind you?`,`The cavern scattered after the last recovery push. Marrin took the fighters deeper. I brought the children and elders here.`,`How long do we have? How many are coming?`,`Dawn. All right. I have nine children to wake up. You need to decide whose side you're on.`]),image:`/scenes/story/story-frostfang-village-65-5.webp`},{...i(`The Confiscated Kits`,`A dry cut in the quarry wall, crates of struck names' belongings stacked as a windbreak`,`Captain Yura`,[`These are confiscated kits from people the Count struck. They were supposed to be processed. They're being used as a windbreak.`,`Wait. This tag is from my old ridge post.`,`Dren Coldewe. I reported him for desertion on day six. On day nineteen, someone without a mark pulled me out of a whiteout. I never saw his face.`,`This is his letter. These plans are for relay lanterns that can find someone without a plate-read. He came back for me.`]),image:`/scenes/story/story-frostfang-village-65-5.webp`,choices:[{text:`Wrap the letter and the lantern plans. They leave with you.`,nextPage:4,trait:`ff65-saved-the-letter`},{text:`Put the letter in Yura's hands. It was always addressed to her.`,nextPage:4,trait:`ff65-gave-yura-the-letter`},{text:`Reseal the crate. The dead keep their kit; the living keep moving.`,nextPage:4,trait:`ff65-resealed-the-kit`}]},{...i(`Dawn Comes Anyway`,`The quarry rim at first light, twelve sealed silhouettes against the snow`,`Narrator`,[`The unit crests the rim exactly on schedule, minus the two hours a captain's signature bought and spent.`,`Below, the camp has packed what nine children and six elders can carry, which is less than hope and more than nothing.`,`The order in your coat says nineteen fighters. The quarry floor says a soup pot and snow-forts.`,`The sealed unit waits on its witness. The word is yours, and the paper is wrong, and the paper is signed by the man who carries shepherds home.`]),image:`/scenes/story/story-frostfang-village-65-5.webp`},{...i(`Ranking Witness`,`The quarry rim, the purge unit forming its sweep line`,`Captain Yura`,[`The order says sweep. There are children below us.`,`Whatever you decide, I'll confirm it. Two officers on the record are harder to ignore than one.`,`They're waiting.`,`Decide.`]),image:`/scenes/story/story-frostfang-village-65-5.webp`}],[{text:`Refuse the order as written. False count, no sweep, on your testimony.`,conclusion:`You declare the sweep void for a false count and sign the refusal. Yura confirms it before the sealed unit can object. By dusk the camp has moved deeper into the mountains. At midnight your testimony reaches Kael's desk. The word NINETEEN is circled in his hand.`,trait:`merciful`},{text:`Escort the camp down the mountain yourself, under pack law.`,conclusion:`You invoke the oldest line in the drill book: the pack walks its slow home. Nine children, six elders, four unsealed, one Jonin, one captain, one runner, walking INTO the village, in the open, daring the Count to refuse its own litany. The gate watch checks the litany, finds no line for this, and opens the gate. Sova enters fifteen names into the book with a steady hand and dares the room to speak.`,trait:`loyal`},{text:`Burn the order in front of the sealed unit and see who salutes.`,conclusion:`Paper burns fast at altitude. The sealed unit watches the order curl to ash. Then one soldier salutes your rank, and the rest follow because the script never told them what to do when the paper was gone. It buys the camp one dawn. It also shows the vault that its own soldiers can be ordered off the hunt.`,trait:`reckless`}]),a(`Frostfang Village`,75,`Yura Breaks the Oath`,`Frostfang Oathbreaker Hunter`,`❄`,[{...i(`Drill Fashion`,`The north tower before first light, Yura's kit laid out in perfect rows`,`Captain Yura`,[`You came. Good. I wrote this down last night so I couldn't change my mind.`,`The blade is clean. The bandages are ready. The kettle is hot. I need you to witness this.`,`I've worn the mark for twelve years. This morning I'm taking it out.`,`Keep talking while I work. If I stop answering, ask me something simple.`]),image:`/scenes/story/story-frostfang-village-75-6.webp`},{...i(`Line by Line`,`The tower room, lamplight, the work begun`,`Captain Yura`,[`The first line is the intake mark. I was nineteen when I took it. There it goes.`,`Talk. Ask.`,`Why now? Because Dren left the Count and still came back for me. No mark made him do it.`,`Second line. Promotion mark. Keep talking. I'm fine. No, don't look at it. Just talk.`]),image:`/scenes/story/story-frostfang-village-75-6.webp`,choices:[{text:`"You turned the holder plate down flat. This is the same hand, finishing the job."`,nextPage:2,requireTrait:`ff70-turned-the-plate`},{text:`Keep her talking. Bell by bell.`,nextPage:3}]},{...i(`The Same Hand`,`The tower room, steam off the kettle`,`Captain Yura`,[`They offered me a holder plate. It would have bound other people to come for me.`,`I thought about Dren walking into that storm because he chose to. I couldn't take the plate after that.`,`You didn't try to persuade me. Thank you.`,`Last line. Hold the lamp closer. If my hand stops, don't help me.`]),image:`/scenes/story/story-frostfang-village-75-6.webp`,choices:[{text:`The lamp steadies. The line comes out.`,nextPage:3}]},{...i(`Self-Injury, Filed`,`The tower stair, a shape climbing with drill-perfect steps`,`Frost Seal Echo`,[`The officer Yura is flagged for damage to Count property.`,`The finding is self-injury. The response is recovery. The Oathbreaker Hunter is dispatched. The Count is whole. The Count will be whole.`,`The asset's service is honored. The asset's confusion is noted. The asset will be corrected and comforted.`,`Warmth is owed. Warmth will be delivered. Stand away from the asset.`]),image:`/scenes/story/story-frostfang-village-75-6.webp`},{...i(`Her Own Name`,`The tower room, Yura on her feet, wrist bound, eyes clear`,`Captain Yura`,[`It calls the mark its property. It calls me confused.`,`The checked are counted. The counted are kept. The kept are fuel. That's what the litany leaves out.`,`It's on the stairs. It moves like Dain did.`,`If you stay, stay because you choose to. I won't ask twice.`]),image:`/scenes/story/story-frostfang-village-75-6.webp`}],[{text:`Stand between the Hunter and her bound wrist. She finishes her morning.`,conclusion:`The Hunter wants the wrist; it has orders about the wrist. It gets you instead, for every stair, every landing, every drill-perfect lunge, while behind you a captain binds her own arm and drinks her tea sitting down. When it finally stops moving, Yura pins her old rank bar to its coat. 'Deliver THAT,' she tells the empty eyes, gently.`,trait:`merciful`},{text:`Fight it side by side. Her first bout as a free name.`,conclusion:`Shoulder to shoulder, no mark binding either of you to the other, which makes every covered flank a CHOICE, which makes it the best fighting either of you has ever done. The Hunter never adapts; nothing sealed ever fought two people who could each walk away and don't. She's laughing by the end. You've never heard her laugh.`,trait:`loyal`},{text:`Let it reach the room, then bar the door behind it. Study it alone.`,conclusion:`You give the Hunter its objective and take the exits, and what happens in the tower room stays between you, it, and the grammar you've been collecting since the border road. It fights exactly as the script fights. It fails exactly where the script fails: the moment Yura addresses it by its OLD name, the one struck from the Count, it hesitates a full second. You write the second down. Seconds like that win wars.`,trait:`suspicious`}]),a(`Frostfang Village`,85,`The Kage Freezes Dissent`,`Oathbound Alpha Guard`,`❄`,[{...i(`The White Silence`,`The central square at dawn, forty-three citizens standing frozen in perfect rows`,`Narrator`,[`They stand in rows in the square, forty-three of them, frost-sealed upright with their eyes open. Neighbors. A baker still dusted in flour. A boy of maybe sixteen with his fists still balled.`,`The village walks around them. Quietly. Eyes down. The way people walk around a thing they've decided not to see, because seeing it costs too much.`,`The wall calls it the White Silence. Preservation, the notice says. Protective custody against the winter of dissent.`,`Each of the forty-three, you learn by asking, filed a grievance, missed a check, or asked the wrong question at roll call. The rows are alphabetical.`]),image:`/scenes/story/story-frostfang-village-85-7.webp`},{...i(`What Harrow Sells`,`The icehouse, Harrow with her collar up and her ledger out`,`Kite Harrow`,[`Those people aren't being punished. Kael is keeping them frozen because the vault feeds on the moment someone decides not to refuse.`,`The deep-script soldiers have almost no refusal left, so the vault can't draw much from them. The forty-three people in the square still have doubts it can use.`,`Frozen at that moment, they can be drawn on again and again.`,`He's storing enough to make a payment. I don't know when it is due.`]),image:`/scenes/story/story-frostfang-village-85-7.webp`,choices:[{text:`"You burned the forged plates. Now show me the real ones' weakness."`,nextPage:2,requireTrait:`ff80-burned-the-plates`},{text:`Go to the vault hall. Face him.`,nextPage:3}]},{...i(`The Rhythm's Flaw`,`The icehouse, a forged mark plate between you on the ice table`,`Kite Harrow`,[`I burned the forged plates. I still remember how they worked.`,`The litany is a four-beat lock: checked, counted, kept, warm. The plate verifies the rhythm, not the person.`,`The frozen people are being kept, but they can't answer a check. That breaks the order the plate expects.`,`Give the plate the right rhythm and it will accept a false answer. That's the weakness.`]),image:`/scenes/story/story-frostfang-village-85-7.webp`,choices:[{text:`To the vault hall.`,nextPage:3}]},{...i(`The Quartermaster of Doubt`,`The vault hall, warm as a hearth, Kael at a table of tally boards`,`Kage Kael Whitefang`,[`Sit down. Nobody argues well shivering.`,`Ninety-one people died the winter before I took the vault. Since then, none.`,`You see forty-three people in the square. I see four hundred people who freeze if the vault runs dry.`,`I've heard every plan for replacing it. None survived the first serious storm.`,`Bring me one that works, not another promise. Until then, the rows stay where they are.`]),image:`/scenes/story/story-frostfang-village-85-7.webp`,choices:[{text:`The Alpha Guard bars the hall.`,nextPage:4}]},{...i(`The Alpha Guard`,`The vault hall doors, the oldest sealed soldier in the village unfolding to full height`,`Narrator`,[`The Alpha Guard was the first man Kael ever sealed, volunteer, back when it was still asked. Forty years of script run wrist to shoulder to heart.`,`He was, the old soldiers say, the kindest man on the wall, once. The seal kept the strength and filed the kindness somewhere it stopped being load-bearing.`,`He bars the hall door with a tenderness that is somehow the worst part, like a father locking a sickroom.`,`The White Silence stands in its rows outside. The vault hums under the floor. The Kage watches you across his tally boards, waiting to see which sum you are.`]),image:`/scenes/story/story-frostfang-village-85-7.webp`}],[{text:`Break the rows out NOW. All forty-three, whatever it costs.`,conclusion:`You go through the Alpha Guard and into the square with chisels and hot water and forty volunteers who materialize the moment somebody goes FIRST. Forty-three people come out of the frost weeping and furious and alive, and the vault's larder empties in an afternoon. The Count's next payment just came due with nothing laid down against it. Kael watches from the hall door and does not stop you, which is the most frightening thing he has ever done.`,trait:`reckless`},{text:`Post yourself at the rows. Nobody freezes, nobody vanishes, on your watch.`,conclusion:`You take up a post the drill book doesn't have: warden of the frozen, in the open square, in view of every window. You check the rows at every bell, aloud, by name. The village starts answering. First one voice, then rows of the living answering FOR the sealed, a roll call the Count never ordered. The White Silence stays sealed, but it is no longer silent, and Kael's cellar has four hundred witnesses now.`,trait:`honorable`},{text:`Map the rows against the vault's intake schedule. Find the payment date.`,conclusion:`Forty-three names, forty-three seal dates, and the vault's draw curve from Sova's meter: they converge. Everything the Count has cellared matures on the same night, three weeks out, when the deep payment falls due. He isn't hoarding doubt out of cruelty. He's short. The vault is SHORT, and the White Silence is the margin, and now you know the date the whole Count either breaks or feeds.`,trait:`suspicious`}]),a(`Frostfang Village`,100,`The Oath Must Break`,`Kage Kael Whitefang, Hollow Oath Tyrant`,`❄`,[{...i(`The Open Ledgers`,`The vault stair, Sova's records room standing open, lamps lit, no keeper`,`Narrator`,[`The records room stands open. Not forced. OPENED. Every vault ledger is out on the reading tables, squared to the table edges, lamps trimmed and burning.`,`Sova is nowhere in the room. Her chair is pushed in. The Count book is gone from its stand, and on the bare wood where it sat for forty years, dead center, lies her pen.`,`It is the tidiest resignation in the history of the village, and the loudest.`,`The stair to the vault door is lit all the way down.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`},{...i(`The Unclosed Door`,`The vault antechamber, Sergeant Essen on post by a door ajar`,`Narrator`,[`Sergeant Essen stands his post at the great hall door with a soldier's perfect bearing.`,`The door is open a hand's width. Cold air walks through it freely.`,`'Door's faulty,' he says, to the middle distance, eyes front. 'Latch must have failed. I've filed a report. These things take time to process.'`,`As you pass, quietly, without turning his head: 'My brother's grievance was the first thing that gate ever took from my family. Take back the rest. The latch will stay faulty as long as it needs to.'`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Through the faulty door.`,nextPage:2}]},{...i(`The Pack Comes Down`,`The vault forecourt, forty-one unmarked figures standing in falling snow`,`Pale Pack Runner`,[`All forty-one of us came. Marrin is up front, and Kessa has the roll-slate. The children are safe with Sova.`,`We talked about it. If this works, we'll answer one roll call here in the forecourt because we choose to.`,`That doesn't mean we forgive anyone.`,`Yura is holding the stair. Go.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`To the stair.`,nextPage:3}]},{...i(`The Stair Held by Choice`,`The vault stair, Yura at the landing, bare wrist bandaged, standing easy`,`Captain Yura`,[`I'm staying on this stair. No mark, no order. Just me.`,`Kael is below at the meter. The payment comes due tonight, and he hasn't left the vault in days.`,`Come back up when this is over. That's an order.`,`Go. I'll keep the door open.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Down, alone.`,nextPage:4}]},{...i(`The Man Fused to the Door`,`The vault floor: a wall of ancient ice, a meter running backward, Kael before it`,`Kage Kael Whitefang`,[`You're on time.`,`That's the vault. The meter reaches zero tonight.`,`The script has moved past my shoulder. I knew the vault was changing other people. I didn't realize it was changing me too.`,`The Count worked when I inherited it. Somewhere along the way, rescue became a quota. I knew, and I kept using it because no one froze. There's something else you need to see.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Look where he is looking.`,nextPage:5}]},{...i(`The Gate Tax`,`The vault's blue-white flame steady above, and beneath the grate a darker pull downward`,`Kage Kael Whitefang`,[`Look beneath the flame. The lower draw is marked with a quartered circle.`,`Its name is Hollow Gate. I signed that draw open thirty years ago and renewed it every year after.`,`The other villages pay it too. Frostfang pays with the choices people surrender to the Count.`,`Dren Coldewe fed the vault and the Gate. I signed both entries. Now show me what you brought. The meter won't wait.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Face him at the meter.`,nextPage:20,trait:`ff100-lower-draw-confessed`}]},{...i(`The Better Roll`,`The vault floor, Dren's lantern plans unrolled against the ice`,`Kage Kael Whitefang`,[`Bring that into the light.`,`Relay lanterns. This is Coldewe's handwriting.`,`You ran a drill on the ridge. One person went missing and the lantern team found him in nineteen minutes without a mark.`,`One drill does not replace the vault. Show me what else you have.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`"Nineteen minutes to find a man in a whiteout. No mark. No vault. And the rows SAW it."`,nextPage:7,requireTrait:`ff88-woke-the-rows`},{text:`Open the drill log to Sova's countersigned pages and read him every line.`,nextPage:8,requireTrait:`ff88-logged-the-drill`},{text:`"Your own wardens filed the report. You've read it four times. You just said so."`,nextPage:9,requireTrait:`ff88-baited-the-wardens`},{text:`Hang Dren's lantern from the meter's frame and let it burn there.`,nextPage:10}]},{...i(`What the Rows Saw`,`The vault floor, the meter's light unsteady`,`Kage Kael Whitefang`,[`The whole wall watched the drill?`,`I had three people tell me the volunteer carried a hidden plate. They were lying.`,`Four hundred people saw him found without the Count.`,`I can't make all of them pretend it didn't happen.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`He looks at the meter a long time.`,nextPage:16}]},{...i(`The Countersigned Log`,`The vault floor, the drill log flat against the ice wall`,`Kage Kael Whitefang`,[`Give me the log.`,`Lantern spacing, sweep times, no plate-read, no draw. Sova signed it.`,`She wouldn't sign an estimate. I taught her better than that.`,`The figures are sound.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`He closes the log with care.`,nextPage:16}]},{...i(`His Own Wardens`,`The vault floor, a warden's report unfolded between you`,`Kage Kael Whitefang`,[`My wardens filed this report.`,`I called the duty officer in and asked whether the drill was real. He said they timed it twice.`,`I accused him of helping you falsify it. He asked to be placed under oath.`,`The report is real. I knew that before you came down here.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`He folds the report in half.`,nextPage:16}]},{...i(`The Lantern on the Meter`,`The vault floor, one lantern burning against a wall of banked exits`,`Kage Kael Whitefang`,[`Coldewe's pattern. Storm glass and a slow wick.`,`I struck him for leaving. Then he came back for Yura without a mark, and I recorded it as self-recovery.`,`I knew it was a lie.`,`Leave the lantern there.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`He does not touch the lantern.`,nextPage:16}]},{...i(`She Answers His Roll`,`The vault stair door opening, Yura coming down with the letter`,`Captain Yura`,[`%name, step back. This is between Dren and me.`,`Kael. Dren Coldewe, ridge post four. Struck for desertion on day six. On day nineteen, he came back for me without a mark or an order.`,`His letter says: 'Tell Yura: being counted isn't the same as being come for.'`,`Dren Coldewe. Present. Twelve years late.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Kael stands very still.`,nextPage:12}]},{...i(`The Door, Answered`,`The vault floor, the meter's hum faltering`,`Kage Kael Whitefang`,[`I remember that letter. I ordered it confiscated.`,`Being counted isn't the same as being come for.`,`No. It isn't.`,`Yura, I knew he came back for you. I changed the report.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`He stands very still.`,nextPage:16}]},{...i(`A Roll Without a Name`,`The vault floor, the drill figures chalked on slate, no letter behind them`,`Kage Kael Whitefang`,[`Nineteen minutes. My wardens timed it twice.`,`But who built the lanterns? Who walked into the storm? Who chose to search?`,`A drill result isn't enough. I need to know whether real people will use this when they're frightened and freezing.`,`Bring me names, or the Count stays.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`He turns back to the meter.`,nextPage:20}]},{...i(`The Undelivered Letter`,`Dren's letter in Kael's scarred hands, unopened`,`Kage Kael Whitefang`,[`That's Coldewe's kit tag. I signed the strike.`,`I tested his lantern pattern in secret. It found a man in nineteen minutes. I buried the result.`,`But this letter was addressed to Yura, and you kept it in your coat.`,`Give it to her. Then come back and tell me what it changes.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`He sets the letter down like a sleeping child.`,nextPage:20}]},{...i(`The Litany, Backwards`,`The vault floor, Sova on the stair with the Count book held open outward`,`Elder Sova`,[`Wait. I need to say this.`,`Kael, I wrote the litany. I taught it to thousands of people.`,`The warm are kept. The kept are counted. The counted are checked. We bound everyone together so nobody could be left behind. We also made it impossible for them to leave.`,`I helped you do that. I'm done. The book stays open from now on.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`She sets the book on the meter.`,nextPage:20}]},{...i(`What's Left`,`The vault floor, Kael looking from the proof to the meter`,`Kage Kael Whitefang`,[`The Count has no answer. Neither do I.`,`Now we see what's left.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Enough. The Count ends here.`,nextPage:20}]},{...i(`Answer for the exemption. You stood outside the Count like Sova.`,`The reckoning`,`Kage Kael Whitefang`,[`Sova gave you the keeper's exemption. Your wrists stayed bare while everyone else paid into the vault.`,`Did you ever look at the intake book and feel relieved it was them instead of you? I did.`,`I felt it for forty years. Then I kept the exemption and called the arrangement necessary.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Enough. The Count ends here.`,nextPage:20}]},{...i(`Answer for my plate. It read someone long gone.`,`The reckoning`,`Kage Kael Whitefang`,[`I read Vess's report about the fogged plate. The vault calls that response an unpaid debt.`,`Someone gave up the choice to leave in your name before you reached Frostfang. The plate recognized that person, not you.`,`I don't know who they were or what they got you out of. If you want the answer, you'll have to find the record outside this village.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Enough. The Count ends here.`,nextPage:20}]},{...i(`Answer for Dren Coldewe. His lanterns are lit on your ridge.`,`The reckoning`,`Kage Kael Whitefang`,[`Dren Coldewe did not desert. Don't ask Sova. I entered the lie.`,`He refused the ridge rotation in front of his post. If I recorded a refusal, everyone else would know saying no was possible. So I called him a deserter.`,`Then he walked into the whiteout and saved Yura anyway. Tell her I knew. Tell her the false report stayed because I wanted it to.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,choices:[{text:`Enough. The Count ends here.`,nextPage:20}]},{...i(`The Meter at Zero`,`The vault floor, the payment due, Kael's script reaching his jaw`,`Kage Kael Whitefang`,[`That's enough.`,`You found another way. I still don't know whether it will survive a real winter, and I can't make myself open the vault and hope.`,`Forty-one struck names are waiting outside. The meter is at zero.`,`If you want to change the Count, take it from me.`,`Show me what holds when nothing is holding it.`]),image:`/scenes/story/story-frostfang-village-100-8.webp`,leftName:`Player`,rightName:`Kage Kael Whitefang`,rightImage:`/portraits/kage-kael-whitefang-hollow.webp`,choices:[{text:`Show him the better Roll: Dren's lanterns found a man with no mark and no vault.`,nextPage:6,requireTrait:`ff88-better-roll-carried`},{text:`Let Yura answer Dren's Roll.`,nextPage:11,requireTrait:`ff88-better-roll-deferred`},{text:`Let Sova read the litany backwards.`,nextPage:15,requireTrait:`ff92-witness-present`},{text:`Show him Dren's letter.`,nextPage:14,requireTrait:`ff88-unfinished-answer`,forbidTrait:`ff88-better-roll-ready`},{text:`Show him the nineteen minutes.`,nextPage:13,requireTrait:`ff88-relay-held`,forbidTrait:`ff65-saved-the-letter`},{text:`Answer for the exemption. You stood outside the Count like Sova.`,nextPage:17,requireTrait:`ff58-took-the-exemption`},{text:`Answer for my plate. It read someone long gone.`,nextPage:18,requireTrait:`ff70-turned-the-plate`},{text:`Answer for Dren Coldewe. His lanterns are lit on your ridge.`,nextPage:19,requireTrait:`ff88-exit-proof-any`}]}],[{text:`Break every mark. No one is guaranteed again. They can only choose.`,conclusion:`The vault cracks. Every banked exit returns to the wrist that surrendered it: old doubts, refusals, and choices coming home years late. The warmth falls back to ordinary fires. Beneath the wall the lower draw pulls once, finds nothing answering, and stops. In the forecourt, the forty-one struck names finish Yura's roll by choice. Kael listens to the last name, then attacks with tears frozen on his face.`,trait:`honorable`},{text:`Bind the vault. Metered, lawful, every struck name a case with your signature.`,conclusion:`The vault stays open under new rules: public draws, consent, and a mark any wearer can revoke. Every historic strike becomes a case again. The lower draw opens once, finds nothing it is allowed to take, and shuts. Sova leaves the book open beside the meter and puts the pen in your hand. Kael bows to the arrangement. The script at his jaw tightens, and he attacks.`,trait:`merciful`},{text:`Take the valve. A better keeper is still a keeper, and it's you.`,conclusion:`Your hand fits the meter like it was cast for it, and you understand, all at once, why the plate fogged at your intake: the vault has been reading you as a keeper since the day you arrived. The script starts at your wrist, warm as a bath, patient as winter. Beneath the meter the lower draw does not close; it waits, patient as the ice, for your first order. Kael's shoulders come down for the first time in forty years. 'Then hold it,' says the vault, with his voice, already counting you.`,trait:`ambitious`}])],"Moonshadow Village":[a(`Moonshadow Village`,4,`No One Saves You`,`Hidden Blade Trainee`,`🌙`,[{...i(`Two Names`,`The registry booth at moonrise, violet lanterns on the canal`,`Shade Master Iro`,[`Welcome to Moonshadow. Sit down. And don't lean on the curtain. It falls if you look at it too hard.`,`Most people here use two names. The day name is for ordinary life. The night name is for work you don't want following you home.`,`I'll take your day name now. You can choose the other one later.`,`Go ahead.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`},{...i(`The First Trade`,`The registry booth, Iro's pen waiting over the intake book`,`Shade Master Iro`,[`All right. Now the intake question.`,`If you had to give something up to get through a bad night, what would go first?`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`,choices:[{text:`"Nothing that keeps someone else safe. That's not for sale."`,nextPage:2,trait:`ms4-trade-protector`},{text:`"Whatever buys me the strongest hand in the room."`,nextPage:3,trait:`ms4-trade-strongest`},{text:`"Anything, to buy back something I lost."`,nextPage:4,trait:`ms4-trade-redeemer`},{text:`"I don't sell. I listen."`,nextPage:5,trait:`ms4-trade-listener`},{text:`"I don't know what I have left to trade."`,nextPage:6,trait:`ms4-trade-unknown`}]},{...i(`A Guardian's Answer`,`The registry booth`,`Shade Master Iro`,[`Nothing that keeps someone else safe. Fair enough.`,`I've written it down, %name. Welcome to Moonshadow.`,`Just make sure you know who you're protecting. People will use that against you.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`,choices:[{text:`Step to the Mirror registry.`,nextPage:7}]},{...i(`A Buyer's Answer`,`The registry booth`,`Shade Master Iro`,[`The strongest hand in the room. A lot of people say that when they arrive.`,`I've written it down, %name. Welcome to Moonshadow.`,`Be careful who offers to help you become important.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`,choices:[{text:`Step to the Mirror registry.`,nextPage:7}]},{...i(`A Debtor's Answer`,`The registry booth`,`Shade Master Iro`,[`Anything. That's a dangerous answer.`,`I've written it down, %name. Welcome to Moonshadow.`,`Whatever you lost, make sure it's really the same thing before you pay to get it back.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`,choices:[{text:`Step to the Mirror registry.`,nextPage:7}]},{...i(`A Listener's Answer`,`The registry booth`,`Shade Master Iro`,[`You listen. Good. Most people here are waiting for their turn to talk.`,`I've written it down, %name. Welcome to Moonshadow.`,`Don't repeat everything you hear.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`,choices:[{text:`Step to the Mirror registry.`,nextPage:7}]},{...i(`An Open Answer`,`The registry booth`,`Shade Master Iro`,[`You don't know what you have left. That's an unusual way to put it.`,`I've written it down, %name. Welcome to Moonshadow.`,`If you work out what you meant, you can tell me. Or don't.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`,choices:[{text:`Step to the Mirror registry.`,nextPage:7}]},{...i(`Half a Second Late`,`The Mirror registry: a disc of still black water that shows every newcomer their true reflection`,`Narrator`,[`Every intake ends at the Mirror registry: a basin of water so still it reads as stone. It shows each newcomer their reflection, and the registry clerks read something in it that they never explain.`,`You lean over. The water shows the lanterns. The curtain. The clerk behind you.`,`Then, half a second late, like a clerk thumbing through files to find your page... you.`,`The registry clerk looks at the delay, then at you, then writes something long in a book that intake clerks are not supposed to have.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`},{...i(`Line Five`,`The canal steps outside, a sharp-eyed woman flipping a coin that isn't a coin`,`Nyx`,[`Hey. Over here. Try not to make it obvious.`,`Your intake paper says the first test is in two nights. It isn't. It's tonight.`,`Nobody will ring a bell or come looking if you miss it. I found that out the hard way.`,`Yard behind the silk house, one bell after moonrise. Bring a weapon.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`,choices:[{text:`The silent yard, one bell after moonrise.`,nextPage:9}]},{...i(`The Silent Yard`,`The silk-house yard at moonrise, a veteran trainee unfolding from the shadows`,`Narrator`,[`The yard is silent because it is BUILT silent: sand raked to swallow footsteps, walls hung with cloth that eats echoes. Whatever happens here happens unheard.`,`The one waiting has done this eleven times. Eleven newcomers, eleven first tests, eleven lessons in the curriculum nobody posts.`,`There is no bell. There is no instructor. There is a woman on the canal steps who sold you the truth for free, watching from the wall with interest that isn't entirely professional.`,`No one is coming. That's the test. That was always the test.`]),image:`/scenes/story/story-moonshadow-village-4-0.webp`}],[{text:`Read the veteran's feet before the first exchange. Silence works both ways.`,conclusion:`The yard eats sound, which means it eats THEIR sound too, and you fight the way the village taught you in its first hour: listening harder than you swing. By the third exchange you know the veteran's rhythm from the sand's whisper alone. On the wall, Nyx stops flipping her coin, which for her is applause.`,trait:`suspicious`},{text:`Take the first strike to give one back harder. Set the price of you early.`,conclusion:`You let the opening cut land so your answer lands twice as loud, and the silent yard learns something about your exchange rate: pain for position, gladly. The veteran resets with new respect and a bleeding lip. By morning, three booths are quoting odds on your next test, and the odds are flattering.`,trait:`reckless`},{text:`End it clean and stand over them until the watchers see who won.`,conclusion:`You finish it efficiently and then hold the yard, unhurried, letting every curtained window get a good long look at the newcomer standing and the veteran down. In Moonshadow, witnesses are currency. You just made your first deposit, and somewhere in the tower, a ledger notes the new arrival's opening balance.`,trait:`ambitious`}]),a(`Moonshadow Village`,15,`The Sold Secret`,`Veiled Hand Collector`,`🌙`,[{...i(`Inside a Locked Room`,`Your quarters, door still bolted, a cipher scroll on the pillow`,`Narrator`,[`The door was bolted from inside. The window latch is unbroken. The dust on the sill is undisturbed, and you checked, because this village has already taught you to check.`,`And on your pillow, folded in thirds, is a cipher scroll in a dead network's hand.`,`The message, when it gives up, is short: village patrol movements, sold in bundles, to an outside buyer, by someone inside. Meet regarding same.`,`Someone put this in a locked room to prove they could. Everything in Moonshadow is a message, and the envelope is usually the loudest part.`]),image:`/scenes/story/story-moonshadow-village-15-1.webp`},{...i(`The Money That Sits`,`Nyx's stall over the dye canal, the scroll flat between you`,`Nyx`,[`Where did you get this? No, wait. Let me read it first.`,`It's an old cipher. Patrol routes and gate rotations, sold every quarter. The buyer is real.`,`But nobody spends the payments. I traced two accounts last season. The money goes in and sits there.`,`That means the sellers aren't doing this for money. Someone is using the payments to make the exchange look ordinary.`]),image:`/scenes/story/story-moonshadow-village-15-1.webp`},{...i(`The Kage's Mercy`,`The canal walk at midnight, Sable Nocturne feeding a lantern flame, alone`,`Kage Sable Nocturne`,[`Walk with me. The scroll can wait.`,`You've heard what people call me. Most of it is deserved.`,`A creditor bought proof of something a merchant's daughter did years ago. He planned to reveal it at her wedding. I bought the proof back this afternoon. That's it burning now.`,`She will never know. You may think she had a right to. I decided she didn't. Decisions like that are my job.`]),image:`/scenes/story/story-moonshadow-village-15-1.webp`},{...i(`The Doorway`,`Your quarters again, and this time the doorway is occupied`,`Veiled Hand Collector`,[`The scroll. You have it. It was placed; you found it; the placement is confirmed received.`,`Understand your position. The scroll was bait. Not for you. For whoever came to DECODE it. We watch what a newcomer does with a secret the way lenders watch what a borrower does with the first loan.`,`You took it to the little dealer on the canal. Interesting. Not the watch. Not the tower. Not a buyer. A FRIEND. We had no column for that.`,`The Collector will now assess. Do hold still. Assessment is quicker when the asset cooperates.`]),image:`/scenes/story/story-moonshadow-village-15-1.webp`},{...i(`Assessment`,`The quarters, the Collector's veils drifting like ink in water`,`Narrator`,[`It moves like a debt: quietly, patiently, absolutely certain it will be paid.`,`Outside the window, Nyx's voice, low and fast: 'That's a Veiled Hand. Tower adjacent, off-ledger, very expensive. Somebody just spent REAL money on finding out what you are. Try to be worth the fee, it annoys them.'`,`The Collector's veils spread across the doorway, sealing the room the way a seal closes a letter.`,`Assessment begins.`]),image:`/scenes/story/story-moonshadow-village-15-1.webp`}],[{text:`Stand your ground in the open. Let it assess an honest answer.`,conclusion:`You fight it in the middle of the room, nothing hidden, nothing held back, and the Collector's assessment gets exactly one entry it cannot price: a person in Moonshadow with no second layer. Its veils flinch, genuinely confused. Somewhere in the tower, a column meant for you stays blank, and blank columns keep certain people awake.`,trait:`honorable`},{text:`Use the room against it. Lamp, shadow, curtain, angle.`,conclusion:`You kill the lamp and make it fight in the dark it came from, and the room becomes a trap with a rent-paying tenant. The Collector withdraws with its veils torn, and its report will read, correctly, that the newcomer turned an assessment into an audit. In this village, that sentence has a price on it by morning.`,trait:`suspicious`},{text:`Break through it and take the fight into the open street.`,conclusion:`You go THROUGH the veils and out the door, dragging the confrontation onto the canal walk where lanterns burn and windows watch. A Veiled Hand, assessed in public: the worst outcome its contract allows. It disengages mid-exchange and pays a forfeiture rather than be seen, and every broker on the water just watched you learn the village's deepest rule: visibility is leverage.`,trait:`ambitious`}]),a(`Moonshadow Village`,25,`Masks Beneath Masks`,`Masked Auction Enforcer`,`🌙`,[{...i(`The Cellar Auction`,`Under the whisper market: a lantern-lit cellar, lots on velvet, buyers in masks`,`Nyx`,[`Keep your hood up and look bored. I bribed the stair guard, but that only gets us so far.`,`Watch the lots. I used to move contraband through here: weapons, relics, private letters.`,`Tonight they're selling patrol schedules and medical records.`,`Lot eleven is a person's name and address. That's new.`]),image:`/scenes/story/story-moonshadow-village-25-2.webp`},{...i(`The Prepaid Buyer`,`The cellar floor, an empty chair with a standing bid`,`Nyx`,[`See the empty chair with the lantern? It has a standing bid on every lot, one step above the highest offer. No limit.`,`Nobody buys everything unless the individual lots don't matter to them.`,`I know everyone who works this market. I don't know who is behind that chair.`,`Someone is collecting the village one file at a time.`]),image:`/scenes/story/story-moonshadow-village-25-2.webp`,choices:[{text:`"Harrow measured me once and refunded the fee. Ask what SHE'D charge to trace that chair."`,nextPage:2,requireTrait:`ms20-respected-the-unsworn`},{text:`Get closer to lot eleven before it sells.`,nextPage:3}]},{...i(`The Appraiser's Trace`,`The cellar's shadowed gallery, Harrow already there, because of course she is`,`Kite Harrow`,[`Don't stare. I'm working.`,`I traced the chair through four brokers. Two are dead. The original account carries a quartered circle, the same mark I've seen in three other villages.`,`The buyer already knows what's in these lots. That's why the auctioneer barely describes them.`,`This isn't shopping. Someone is making an inventory.`]),image:`/scenes/story/story-moonshadow-village-25-2.webp`,choices:[{text:`Lot eleven goes up.`,nextPage:3}]},{...i(`No White Invitation`,`The cellar floor, the auctioneer's hand pausing, every mask turning`,`Narrator`,[`Lot eleven rises on its velvet: a name, an address, a life with a reserve price.`,`And the auctioneer stops, because the stair guard is signaling, because somewhere between the gallery and the floor, somebody finally asked the bad question, and it was probably the one you're wearing on your face.`,`'The house notes,' the auctioneer says smoothly, 'a guest without a white invitation.'`,`The masks turn. The Enforcer detaches from the wall where it has stood so still you priced it as furniture. Nyx exhales a word that no ledger would print, and names her exit, and doesn't take it, and stays at your shoulder.`]),image:`/scenes/story/story-moonshadow-village-25-2.webp`},{...i(`The House Rules`,`The cellar, the Masked Auction Enforcer rolling its shoulders`,`Nyx`,[`The Enforcer won't damage the lots. Use that.`,`The house is protecting the buyer's chair, and the buyer is tied to the quartered circle.`,`Lot eleven sells in ninety seconds.`,`I'll get the name. Keep that thing busy.`]),image:`/scenes/story/story-moonshadow-village-25-2.webp`}],[{text:`Fight the Enforcer as a screen. Nyx palms lot eleven in the chaos.`,conclusion:`You give the cellar its show, loud and central, and while every mask watches the Enforcer earn its retainer, a canal broker with quick hands makes a bloodline name disappear off velvet. The house records the lot as 'withdrawn.' The chair's proxy bid lands on nothing, prepaid, unrefundable. Somewhere, an inventory develops its first discrepancy.`,trait:`suspicious`},{text:`Stand on the auction table and say what's being sold, mask off.`,conclusion:`You name the lots out loud, bare-faced, in the one room built to never hear it: schedules, medicine, a living name, YOUR neighbors, sold to a chair. The cellar doesn't riot; this is Moonshadow, riots are for the daylight villages. But masks start leaving, one by one, and an auction with no bidders is just theft with candles. The house will remember your face. That was rather the point.`,trait:`honorable`},{text:`Put the Enforcer through the buyer's chair. Let the house bill the circle.`,conclusion:`You end the fight ON the proxy chair, splintering the standing bid's little lantern under two hundred pounds of house muscle, and the message writes itself in the wreckage: come shop in person. The auctioneer is very calm in the way of a man composing an extremely difficult letter to an extremely dangerous client. Nyx laughs the whole swim home.`,trait:`reckless`}]),a(`Moonshadow Village`,35,`The Hollow Moon Contract`,`Contract-Bound Shadow`,`🌙`,[{...i(`The Bleeding Page`,`A safe room over the canal, a contract that darkens in moonlight`,`Nyx`,[`I took the rider attached to lot eleven. Read it under the moon.`,`In lamplight it looks like a purchase memo. The real text only appears out here.`,`Sable Nocturne is the contracting party. It pays for the disappearance of everyone on this list.`,`They're all talented people with influence. She isn't removing criminals. She's removing possible successors.`]),image:`/scenes/story/story-moonshadow-village-35-3.webp`,choices:[{text:`"I stood at a stone once that only opens for a kept no. This page smells the same."`,nextPage:1,requireTrait:`rd34-kept-my-no`},{text:`Ask what's on the other end of the contract.`,nextPage:2}]},{...i(`The Kept No`,`The safe room, the contract pinned under a lamp it doesn't like`,`Nyx`,[`A stone opened for a witnessed refusal? Where did you find that? No, later.`,`This rider does the opposite. It treats silence as permission.`,`The dark text isn't ordinary ink. Each name is already partially bound to the contract.`,`If the document is destroyed, those claims may break with it.`]),image:`/scenes/story/story-moonshadow-village-35-3.webp`,choices:[{text:`The lamplight bends.`,nextPage:2}]},{...i(`The Counterparty`,`The safe room, the lamp's light bending toward the wall like a bow`,`Hollow Moon`,[`The rider is read. The reading is noted. The reader is... ah. The reader is the discrepancy itself. How efficient. Two errands, one lamp.`,`Be at ease. The Hollow Moon does not collect tonight. Tonight is a courtesy call, itemized as goodwill.`,`Your Kage sells us her rivals and calls it protection. Her predecessor sold us his doubts and called it clarity. The seat sells; the seat is FOR selling; ask it, when you meet. We merely honor the standing order.`,`You, though. You keep appearing in inventories with no purchase history. The chair noted it. The cellar noted it. Now the lamp notes it. Something acquired you before us, discrepancy, and the Hollow Moon does not bid on encumbered goods. Resolve your prior lien. Then we may talk terms.`]),image:`/scenes/story/story-moonshadow-village-35-3.webp`},{...i(`The Contract's Guard`,`The safe room, a shadow detaching from the contract itself`,`Nyx`,[`It said you have a prior claim on you. Something may already own part of your record. We deal with that later.`,`The shadow is bound to the page. Its job is to keep the contract intact.`,`Break the binding and the eleven claims should release. Keep the page whole and I may be able to trace whoever wrote it.`,`The lamp is going out. Decide.`]),image:`/scenes/story/story-moonshadow-village-35-3.webp`}],[{text:`Study the binding as you break it. Learn the drafter's hand.`,conclusion:`You take the guard apart the way Nyx reads a cipher: slowly, greedily, noting every clause it bleeds. When the binding snaps, eleven liens release, and you hold the drafter's grammar in your head: the quartered circle writes its contracts in surrendered trust, and now you can recognize the handwriting. Nyx calls it the most profitable fight she's ever billed nothing for.`,trait:`suspicious`},{text:`Break the escrow outright. Eleven names go free tonight.`,conclusion:`You put the guard down and the binding with it, and the rider's moonlit text pales line by line as eleven half-collected people are quietly returned to themselves. They'll never know. That's the strange ache of it: the best thing you've done in this village, and its whole nature is that nobody can ever thank you. Nyx writes the date in her book anyway. 'Somebody should hold the receipt,' she says.`,trait:`honorable`},{text:`Keep the rider intact. A contract with HER name on it is leverage.`,conclusion:`You fight the guard to a draw and reseal the page, escrow and all, into a moon-proof case. Eleven liens stay live, and you own the only document on the canal that binds the Kage's own name to the trade. Nyx looks at the case, then at you, pricing something she doesn't say aloud. 'Leverage on a spider,' she finally offers, 'is web. Remember which of you spins faster.'`,trait:`ambitious`}]),a(`Moonshadow Village`,50,`Jonin of the Hidden Knife`,`Jonin Trial: Mirror Assassin`,`🌙`,[{...i(`The Mirrored Chamber`,`The tower's mirrored chamber, a hundred reflections, one Kage`,`Kage Sable Nocturne`,[`Come in. Ignore the mirrors.`,`I know about the cellar, the rider, and the thing you saw in the lamp. I've read every report on you.`,`I could have you killed. I'm promoting you instead. Kneel.`,`The rank is real. So is the assignment that comes with it. You should assume I'm keeping you close because I don't trust you.`]),image:`/scenes/story/story-moonshadow-village-50-4.webp`,choices:[{text:`"You reported the booths once. She knows. Watch her watch you."`,nextPage:1,requireTrait:`ms42-reported-the-booths`},{text:`Take the errand and read it later.`,nextPage:2}]},{...i(`The Report She Kept`,`The mirrored chamber, Sable drawing one page from her sleeve`,`Kage Sable Nocturne`,[`I have the report you filed about the confession booths. The tower intercepted it before it reached the watch.`,`Someone files a complaint every few years. Usually they describe the fear and stop there.`,`You mapped the drain.`,`That is why I'm promoting you. I want you close enough to watch.`]),image:`/scenes/story/story-moonshadow-village-50-4.webp`,choices:[{text:`The corridor, after.`,nextPage:2}]},{...i(`Collateral That Reports`,`The tower corridor, Nyx leaning where the guards pretend not to see her`,`Nyx`,[`Jonin. That was quick.`,`Your new rank means the tower will record everything you do more closely. Be careful what you say around me too.`,`I had a badge once. It took me a month to understand it was mostly there to make me easier to track.`,`Read the assignment twice. Small errands are how they find out what you'll do on a larger one.`]),image:`/scenes/story/story-moonshadow-village-50-4.webp`,choices:[{text:`The trial waits below.`,nextPage:3}]},{...i(`The Mirror Assassin`,`The trial floor beneath the chamber, your own reflection stepping out of the glass`,`Kage Sable Nocturne`,[`Every Moonshadow Jonin takes this trial.`,`The Mirror keeps a reading of everyone registered here. It uses that reading to make the opponent in front of you.`,`It knows whatever the registry knows about you. It also shares the registry's gaps.`,`Yours appeared half a second late. Begin when you're ready.`]),image:`/scenes/story/story-moonshadow-village-50-4.webp`}],[{text:`Fight it to a standstill, then claim ITS reading as your property.`,conclusion:`You beat the reflection to one knee and then, before the whole trial floor, invoke the market's own first law: possession of a defeated asset. The Mirror's reading of you, every priced page of it, transfers to YOUR custody, and the registry suddenly holds nothing on the newest Jonin but a receipt. Sable applauds, twice, slowly. In her drawer of almosts, something graduates.`,trait:`ambitious`},{text:`Study its moves. It's built from the registry's file on you; learn the file's gaps.`,conclusion:`You fight defensively and take inventory: everything the reflection knows, the registry knows, and everything it FUMBLES is a page your file is missing. By the last exchange you have a map of your own blind spot in their books, and it is exactly the shape of the things you've done unwitnessed. The asset dissolves, confused. You leave the trial knowing precisely what Moonshadow cannot see.`,trait:`suspicious`},{text:`Refuse to fight yourself. Stand still and let it choose.`,conclusion:`You ground your blade and face the asset open-handed, and for eleven long breaths the trial floor holds two identical people deciding what they are. Then the reflection grounds its blade TOO, and the Mirror, which has priced ten thousand candidates, records its first tie. Sable stands. 'The registry has no column for that,' she says, and the sentence sounds, in her mouth, like both a promotion and a threat.`,trait:`honorable`}]),a(`Moonshadow Village`,65,`Mission to Kill a Witness`,`Veiled Hand Executioner`,`🌙`,[{...i(`The Unwritten Order`,`The tower's night office, an errand delivered as a whisper, nothing on paper`,`Narrator`,[`The order arrives the way the worst ones do here: verbally, thirdhand, deniable. No seal, no page, no file. The small errand's true face, finally shown.`,`A shrine witness on the eastern canal has been copying names. The witness dies tonight. The Jonin of the Hidden Knife handles it personally. The tower never asked.`,`You've learned the village's grammar well enough to translate: someone with your title is expected to wipe the blade in the tower's direction.`,`The shrine on the eastern canal keeps its lamps low. Witnesses usually do.`]),image:`/scenes/story/story-moonshadow-village-65-5.webp`},{...i(`The Copied Names`,`The canal shrine, an old keeper laying pages flat with shaking hands`,`Shrine Witness`,[`You're the one they sent. Sit down and read before you decide what to do with me.`,`There are three hundred eleven names here, going back forty years. The booth records say they were sold downward. They may still be alive.`,`Their families think they left. I made copies so the original records couldn't be erased without a trace.`,`Read the third page. I think that's why the tower sent you instead of someone it trusts.`]),image:`/scenes/story/story-moonshadow-village-65-5.webp`,choices:[{text:`Read the third page.`,nextPage:2}]},{...i(`The Third Page`,`The shrine, one page under the low lamp`,`Narrator`,[`The third page is newer than the others. The names on it are children.`,`Halfway down, in the witness's careful duplicate hand, one entry is ringed where the original was ringed: a girl, aged nine at sale, her true name traded by her own hand, 'consideration: one winter's food.' Sold to a buyer marked with a quartered circle. Storage fees current, paid quarterly, forty years running.`,`The name is one you know. You know it because a woman on the canal steps gave you its DAY-name version for free, with a coin that isn't a coin, on your first night in this village.`,`Nyx's true name has a holder, and a price, and a receipt, and she has been buying information about that file her whole life without ever once being able to afford the file itself.`]),image:`/scenes/story/story-moonshadow-village-65-5.webp`,choices:[{text:`Take Nyx's file page. Whatever else tonight becomes, this leaves with you.`,nextPage:3,trait:`ms65-saved-the-file`},{text:`Send the page to Nyx tonight, unsigned. Hers to hold first.`,nextPage:3,trait:`ms65-gave-nyx-the-file`},{text:`Copy nothing, take nothing. The witness's set stays whole and hidden.`,nextPage:3,trait:`ms65-resealed-the-crate`}]},{...i(`The Second Knife`,`The shrine door, a second figure arriving with excellent manners`,`Veil Adaza`,[`Evening. Veil Adaza. We met at the Black Bridge.`,`I received the same order you did. Same witness, same night. The tower is testing both of us.`,`My order says that if you hesitate, I finish the job.`,`The Executioner behind me is here in case we both refuse. What do you want to do?`]),image:`/scenes/story/story-moonshadow-village-65-5.webp`,choices:[{text:`"I've stood between bolts and the chained before. I'm doing it again."`,nextPage:4,requireTrait:`rd52-shielded-the-line`},{text:`Answer with your stance, at the shrine door.`,nextPage:4}]},{...i(`The Executioner's Patience`,`The shrine yard, the Veiled Hand Executioner unfolding from the dark`,`Veil Adaza`,[`I was hoping you'd protect the door.`,`The witness is still copying. The tower wants those names reduced to one set, and it wants to see whether you obey.`,`The Executioner won't negotiate. I already tried once.`,`It's coming.`]),image:`/scenes/story/story-moonshadow-village-65-5.webp`}],[{text:`Stand between the Executioner and the shrine. The copying continues.`,conclusion:`You plant yourself at the shrine door and make the tower's prepaid contract earn every clause, and behind you, through the whole fight, the sound never stops: an old keeper's brush, copying names, steady as canal water. Adaza watches from the wall, scrupulously neutral, and at the end files the only report she can: the first knife stands where it's pointed AT, not where it's pointed FROM.`,trait:`merciful`},{text:`Unmask the errand: shout the tower's order to the whole canal.`,conclusion:`You shout the order across the canal: the tower sent an Executioner for a shrine keeper whose crime was copying the names of the sold. Windows open. Booths empty. By the time the Executioner reaches the bridge, three hundred people know why it is there. It cannot finish a deniable order in front of that many witnesses.`,trait:`reckless`},{text:`Let Adaza engage first. Read the Executioner's contract as it fights.`,conclusion:`You let Adaza take the first three exchanges while you watch the Executioner obey its orders. Strike on breach. Withdraw on payment. On the fourth exchange you catch the termination phrase and speak it. The thing stops. Adaza checks it for movement, then looks at you. 'I'm not putting this one on an invoice,' she says.`,trait:`suspicious`}]),a(`Moonshadow Village`,75,`Nyx Chooses a Side`,`Shadow Network Hunter`,`🌙`,[{...i(`The Red Moon Ledger`,`A rooftop over the whisper market, red moon, Nyx's ledger open to a page of shame`,`Nyx`,[`Sit down. Have a drink. I need to tell you something.`,`Six months ago, people working for Hollow Gate offered to buy information about you. I accepted.`,`I sold them lies. Fake routines, false debts, places you never went. They paid full price every time.`,`After a while, I understood they didn't care whether the information was true. They wanted me to keep choosing to sell you. I'm sorry.`]),image:`/scenes/story/story-moonshadow-village-75-6.webp`},{...i(`The Free Envelope`,`The rooftop, one envelope on the tiles between you, unpriced`,`Nyx`,[`This envelope names Hollow Gate's agent inside the tower. It includes the room and the hours when their correspondence arrives.`,`It is worth more than everything I own.`,`Take it. I don't want anything from you.`,`I stopped keeping a file on you too.`]),image:`/scenes/story/story-moonshadow-village-75-6.webp`,choices:[{text:`"You named the lattice once. Now name its agent out loud with me."`,nextPage:2,requireTrait:`rd74-bound-the-lattice`},{text:`Take the envelope.`,nextPage:3}]},{...i(`Naming It`,`The rooftop, the red moon deepening`,`Nyx`,[`The lattice was the old name for the same network. The tower calls it Hollow Gate now.`,`Four village anchors feed one system, and each tower has someone handling its messages.`,`The agent in our tower is named in that envelope.`,`There. We both know it. Neither of us gets to pretend this is only business anymore.`]),image:`/scenes/story/story-moonshadow-village-75-6.webp`,choices:[{text:`The moon's light bends.`,nextPage:3}]},{...i(`The Lecture`,`The rooftop, the red moonlight pooling into a standing shape`,`Hollow Moon`,[`Discrepancy. And the little dealer. How tidy; the audit walks to us.`,`Dealer. Your last six months of product have been reviewed. The fiction was noted from the first invoice; fiction is FINE, dealer. We told you: the transaction is the crop. But tonight's entry. The envelope. The 'free.'`,`There is no column for free. Free is not a price. Free is a REFUSAL wearing a price's clothing, and refusals witnessed in the open become... load-bearing. You have made yourself structurally significant, dealer, and structures get surveyed.`,`The Hollow Moon extends one final offer at preferential terms: reprice tonight. Any figure. Name literally any figure, and the ledger heals, and the survey forgets the roof. Decline, and the discrepancy's contagion is confirmed, and containment becomes billable.`]),image:`/scenes/story/story-moonshadow-village-75-6.webp`},{...i(`The Shadow Network Hunter`,`The rooftop, shapes rising from every drain and gutter the market owns`,`Nyx`,[`That's the Hunter. I was afraid they'd send it.`,`It doesn't kill people. It takes them back and removes whatever made them refuse. I've met people after that happened.`,`No. I'm not taking the envelope back.`,`Back to back. Don't let it get hold of either of us.`]),image:`/scenes/story/story-moonshadow-village-75-6.webp`}],[{text:`Watch the Hunter's recovery grammar. Learn what un-prices a person.`,conclusion:`Fighting back to back with Nyx, you see the Hunter build its hold from her old receipts. One record after another locks into place until it reaches the free envelope. There is no price on it, so the chain breaks. The Hunter loses its grip in the same place every time. Nyx notices too. 'Good,' she says, breathing hard. 'I was hoping that mattered.'`,trait:`suspicious`},{text:`Hold the line at her shoulder until the moon sets. No reading, no angles.`,conclusion:`For one whole night you are precisely what the ledger says cannot exist: unpriced help, standing its ground for nothing. The Hunter probes for the transaction underneath and finds only the thing itself. At dawn it withdraws, unpaid and unpaid-able, and Nyx sits down hard on the tiles and laughs until she cries, and then just cries, and neither of you invoices the other for witnessing it.`,trait:`honorable`},{text:`Counter-offer the Hollow Moon, mid-fight: the agent's name for its retreat.`,conclusion:`You negotiate DURING the recovery, shouting terms over the Hunter's shoulder at the moonlight itself: call it off, and the envelope's name stays private one more season. The Hollow Moon pauses. Considers. ACCEPTS, at terms, logged. Nyx stares at you as the shapes drain back into the gutters. 'You just opened an account with it,' she says quietly. 'Friend. Nobody closes those. I checked.'`,trait:`ambitious`}]),a(`Moonshadow Village`,85,`The Kage Owns Every Secret`,`Veiled Hand Grandmaster`,`🌙`,[{...i(`The Night of Open Files`,`The whisper market at dawn, forty years of intake dumped on every doorstep`,`Narrator`,[`It happens in one night. Every alias, every debt, every confession the booths ever drained: unsealed, copied, and delivered. Doorsteps. Stall counters. Nailed to the shrine door. Forty years of the village's held truths, given back all at once, like a dam deciding rain was a mistake.`,`The market convulses. Marriages detonate at breakfast. Three brokers flee before the fish carts even arrive. A moneylender reads his own file weeping on the canal steps, and nobody stops to watch, because everybody is reading their own.`,`It should be chaos, and it is. It should be random, and it is NOT.`,`Every unsealed file went to its subject. Not to enemies. Not to buyers. To the PERSON. Whatever this is, it has a principle in it, buried somewhere in the cruelty.`]),image:`/scenes/story/story-moonshadow-village-85-7.webp`},{...i(`The Controlled Burn`,`Nyx's stall, shutters up, her own returned file unopened on the counter`,`Nyx`,[`Mine came too. The tower used every courier it had to return the files in one night. Sable ordered it.`,`A transfer notice arrived at midnight. Someone with a quartered-circle seal is taking ownership of the Mirror.`,`Sable returned everything she could so the buyer couldn't take it.`,`My file is here. I've wanted it for forty years, and now I can't open it.`]),image:`/scenes/story/story-moonshadow-village-85-7.webp`,choices:[{text:`"You pulled Harrow back from the Mirror job. Now ask her WHO the buyer is."`,nextPage:2,requireTrait:`ms80-pulled-her-back`},{text:`Climb to the tower before the transfer lands.`,nextPage:3}]},{...i(`The Buyer's Name`,`The stall's back room, Harrow arriving with her collar up and her license folded away`,`Kite Harrow`,[`You kept me from taking the Mirror contract. I owe you this.`,`The client never asked what any secret said. They only asked how much the Mirror could hold and how long it retained a copy.`,`They want the container, not the information. It's the same pattern as the reserve, the vault, and the Rootfire.`,`Sable knows. Go to the tower before the transfer finishes.`]),image:`/scenes/story/story-moonshadow-village-85-7.webp`,choices:[{text:`Up the tower.`,nextPage:3}]},{...i(`The Empty Archive`,`The tower archive, stripped to bare shelves, Sable alone in the wreck of her life's work`,`Kage Sable Nocturne`,[`Come in. I returned the files. All of them.`,`Before I did, I found a prior claim on every record in the archive. The mark was the quartered circle. I thought I owned this collection. I was maintaining it for Hollow Gate.`,`The transfer still happens tonight. Because the shelves are empty, the buyer takes the Mirror instead. The Mirror kept a copy of everything the booths collected.`,`And no, I'm not going to break it because the market survived one bad night. It may not survive the next month. Until you show me something safer, I hold the tank.`]),image:`/scenes/story/story-moonshadow-village-85-7.webp`,choices:[{text:`Take the founding lease with you. The blank line no hand ever signed is evidence too.`,nextPage:4,trait:`ms85-copied-the-blank-line`},{text:`Leave the paper. Bring her the living truth instead.`,nextPage:4}]},{...i(`The Veiled Hand Grandmaster`,`The tower stair, the eldest Veiled Hand unfolding from the shadows it taught`,`Narrator`,[`The Grandmaster of the Veiled Hand has served four Kages and outlasted three attempted successions. It taught the Collectors their patience and the Executioners their clauses, and it stands the stair tonight not for Sable, but for the ORDER of things.`,`Below, the market reads itself by lamplight, forty years of truth loose in the streets. Above, a Mirror waits for its new owner, black and still and patient as escrow.`,`The Grandmaster's veils settle. Its contract, the oldest in the village, has one clause: nothing reaches the tank unpriced.`,`You have never once priced correctly here. That was always going to come due tonight.`]),image:`/scenes/story/story-moonshadow-village-85-7.webp`}],[{text:`Stand with the market: shepherd the night of open files at street level.`,conclusion:`You spend the fight and the night in the streets: breaking up two duels, guarding the shrine's copied lists, sitting with a moneylender while he finishes his own file and, at the end, folds it closed and shakes your hand. The village survives its own truth by morning, bruised and strangely lighter. Word climbs the tower: the newcomer held the MARKET together, unpaid. The Grandmaster's veils note the figure that refused to climb, and the note reads, in its old grammar, like respect.`,trait:`loyal`},{text:`Go through the Grandmaster now. The Mirror doesn't change hands tonight.`,conclusion:`You take the stair by force, veils tearing like old contracts, and reach the tank chamber with the transfer's escrow already glowing on the glass. The Grandmaster yields the stair a step at a time, and by the top it has stopped fighting and started WATCHING, the way old instruments watch a new hand take the work. The transfer clause hangs mid-air, unexecuted, waiting on tonight's outcome. Nothing about it is settled. But it did not land on schedule, and schedules were the buyer's whole religion.`,trait:`reckless`},{text:`Audit the lease itself. Every contract that binds has a breach clause.`,conclusion:`While the market burns through its truths, you sit in the stripped archive with the one document Sable never burned: the original lease, older than the village's name, quartered circle on the seal. You read it the way the shrine witness copied: patiently, twice. And you find them: the payment schedule, the balloon clause, and there, in the oldest hand, the breach terms. What no one signed, no one owes. Somebody in this lease's chain of custody never actually SIGNED. The line is blank. It has been blank for four hundred years, and every collection since has been enforcement of a debt nobody sealed.`,trait:`suspicious`}]),a(`Moonshadow Village`,100,`The Moon Belongs to No One`,`Kage Sable Nocturne, Hollow Moon Sovereign`,`🌙`,[{...i(`The Black Moon`,`The tower summit stair, the moon overhead gone black as the Mirror`,`Narrator`,[`The moon goes black at dusk, and nobody in the market needs it explained: the collection date arrived. The buyer's escrow sits full. Tonight the account of Moonshadow settles, one way or the other.`,`The village does not climb behind you. It does something the tower has no procedure for: it stays home with every lamp lit. Returned files stand open in the windows, and the whole canal watches the books balance from inside its own houses. Only the ones with business at the top take the stairs: the shrine witness with her copied names, and a moneylender holding his own file like a lantern.`,`At the summit landing, on the last step, someone has left a cup of canal tea, still warm, and a note in a broker's quick hand: 'Argue dry and you'll lose. No charge. That's twice now. N.'`,`The Mirror chamber stands open. It has been waiting half a second longer for you than for anyone.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`},{...i(`At the Chamber Door`,`The summit door, Nyx with her returned file tucked unopened in her coat`,`Nyx`,[`You have to go in alone. I checked for another way. There isn't one.`,`My file is still closed. I'm keeping it that way until you come back down.`,`Harrow was right about one thing. Someone got to Sable before Sable got to the rest of us. That doesn't excuse her.`,`I'll hold the door. Come back.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enter the Mirror chamber.`,nextPage:2}]},{...i(`The Woman and the Tank`,`The Mirror chamber, the black glass vast and still, Sable's shadow no longer matching her`,`Kage Sable Nocturne`,[`You're here. Good.`,`The Mirror holds a copy of every secret surrendered to this village. It transfers to Hollow Gate tonight.`,`My shadow stopped matching me in the spring. The Gate is taking its payment from me too. I renewed the lease every quarter, so don't mistake that for innocence.`,`Three people challenged me before you. I destroyed them. You've read the files.`,`Go on. Show me why this should be different.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Face her before the glass.`,nextPage:25}]},{...i(`The Better Truth`,`The Mirror chamber, the Returning's receipts fanned on the black glass`,`Kage Sable Nocturne`,[`Let me see those.`,`Eleven files returned with the owners' consent. I read the reports.`,`One week without a killing does not make the market safe. How many people were threatened afterward? How many returns were staged?`,`Show me the rest.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`"Eleven files returned before witnesses. Zero fires. The market SAW it hold."`,nextPage:4,requireTrait:`ms88-open-returns`},{text:`Lay the sealed receipts on the glass and read her every countersigned line.`,nextPage:5,requireTrait:`ms88-sealed-receipts`},{text:`"Your own booths ran the numbers. The market repriced returning at survivable."`,nextPage:6,requireTrait:`ms88-baited-the-market`},{text:`Set the child's bill of sale on the glass and let its smallness argue.`,nextPage:7}]},{...i(`What the Market Saw`,`The chamber, the black glass showing the market's lanterns far below`,`Kage Sable Nocturne`,[`All eleven happened in the open market?`,`My people found no killings tied to the returns. I had them check three times.`,`If the market saw it work, other people will try it whether I allow them to or not.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`The glass moves.`,nextPage:8}]},{...i(`The Countersigned Receipts`,`The chamber, receipts flat on the glass, her finger moving line to line`,`Kage Sable Nocturne`,[`Give them to me.`,`Owner verified, witness signed. Eleven times. The shrine witness, the moneylender, and Iro?`,`These signatures could have been bought. No. I know three of these hands. They weren't.`,`The receipts are valid.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`The glass moves.`,nextPage:8}]},{...i(`The Market's Own Arithmetic`,`The chamber, a booth's price-slate held up to the glass`,`Kage Sable Nocturne`,[`I saw the new prices at dusk. I had two clerks punished because I thought they forged the slates.`,`They didn't. Every booth reached the same conclusion on its own: returning a file is survivable, and holding one is becoming dangerous.`,`The market has already moved without me.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`The glass moves.`,nextPage:8}]},{...i(`The Unopened File`,`The chamber, one file on the black glass, still closed`,`Kage Sable Nocturne`,[`That's Nyx's file. She was nine when she sold the name for food.`,`She has had it for days and still hasn't opened it?`,`I don't know what you think that proves.`,`No. I do. She no longer needs the file to tell her who she is.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`The glass moves.`,nextPage:8}]},{...i(`The Names in the Glass`,`The Mirror chamber, the receipts against the tank, the reflection changing`,`Narrator`,[`The receipts lie against the black glass, and for the first time in forty years the Mirror reflects the names on the signatures instead of the keeper's face.`,`A single clear line crosses the tank, and a voice follows it, level and old. OWNERS VERIFIED. RETURN CHAIN WITNESSED. CONSENT CONFIRMED. NO HOLDER REQUIRED.`,`'The First Reflection,' Sable says, very quietly. 'The Mirror's oldest instruction. Witness the truth. Then let it go. We kept the witnessing and removed the letting go.'`,`She straightens, and does not look away from the glass again.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`The glass stills.`,nextPage:12}]},{...i(`Her Own Name`,`The chamber door opening, Nyx crossing the black glass floor`,`Nyx`,[`%name, step back. I need to say this myself.`,`Sable, you know the name I use. You also have the record of the name I sold when I was nine because I needed food.`,`My name is Nerissa Vale. My mother chose it. It belongs to me.`,`That's all.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`The glass goes very still.`,nextPage:10,trait:`ms100-nyx-named-herself`}]},{...i(`The Oldest Rule Answers`,`The Mirror chamber, one clear line crossing the black tank from end to end`,`Narrator`,[`The glass stays still for one breath. Two. Then it ripples, and the ripple is wrong for this room: not the Hollow Moon's red, but a single clear line, crossing the black tank from one end to the other.`,`A voice follows the line, level and old, from a place in the glass no drain reaches. NAME SPOKEN BY OWNER. WITNESSED. NOT SURRENDERED. NOT FOR SALE.`,`A second ripple follows. NO HOLDER REQUIRED.`,`For the first time tonight, Sable Nocturne takes a step back from her own Mirror.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Sable stares at the glass.`,nextPage:11}]},{...i(`The Tank Hears a Name`,`The chamber, the Mirror's stillness broken by one slow ripple`,`Kage Sable Nocturne`,[`Nerissa Vale. I know that name.`,`That voice from the glass is in the oldest Mirror plans. I thought it was ceremonial.`,`The original instruction was to hear a truth, verify its owner, and release the claim. Hollow Gate added the part where the Mirror kept a copy.`,`I knew the plans. I kept the copies anyway.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`She steps back from the glass.`,nextPage:12}]},{...i(`Unlisted`,`The Mirror chamber, Sable's shadow finishing its departure`,`Kage Sable Nocturne`,[`I have nothing left to bargain with.`,`Come find out what that leaves.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Returns Without Names`,`The chamber, the return figures chalked plain, no receipts behind them`,`Kage Sable Nocturne`,[`Eleven returns and no violence tied to them. I had the figures checked three times.`,`But I don't have names, signatures, or proof that the owners agreed.`,`I'm not opening a four-hundred-year-old tank on an anonymous report.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`She turns back to the glass.`,nextPage:25}]},{...i(`The File in Your Coat`,`Nyx's file in Sable's hands, hers to weigh, unopened`,`Kage Sable Nocturne`,[`This is Nyx's bill of sale. Her signature is on it, and it was still in your coat.`,`You saved it and told yourself you were keeping it safe.`,`That's what I told myself about the whole archive.`,`Give it back to her. Then tell me how different you are.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`She sets the file down with terrible gentleness.`,nextPage:15}]},{...i(`From the Door`,`The chamber threshold, Nyx one step inside, not crossing the black glass`,`Nyx`,[`That was mean.`,`Accurate, which is worse. Hand it back when we're down the stairs, would you? I don't like my file this high up.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`The glass waits.`,nextPage:25}]},{...i(`Iro Reads the Manifest`,`The chamber stair, Iro arriving with the buyer's manifest and an expression nobody has ever purchased`,`Shade Master Iro`,[`Don't touch that. I need to show it to her myself.`,`Sable, this is the buyer's transfer manifest. Everything in the Mirror is listed.`,`I'm on line four hundred and six. Not my accounts. Me.`,`I spent forty years thinking I was part of the market. I was part of the inventory. So I'm done helping you protect it.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`He sets the manifest beside the glass.`,nextPage:25}]},{...i(`The Blank Line`,`The Mirror chamber, the founding lease unrolled on the black glass, older than the tank`,`Kage Sable Nocturne`,[`The founding lease. The first holder never signed it.`,`I found the blank line in my first year as Kage.`,`I could have challenged the lease then. I was afraid of what Hollow Gate would do, so I renewed it every quarter for forty years.`,`The original debt may be invalid. My signatures are not.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Answer for the shelf. You've been paying its fee for seasons.`,`The reckoning`,`Kage Sable Nocturne`,[`So Iro sold you a shelf. That gave you access to other people's files. He always did know how to make a trap look private.`,`Did you ever open one just because you could? Take your time. I know what the honest answer costs.`,`I did the same thing for forty years and called it protection. The scale is different. The excuse isn't.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Answer for my file. I burned it in front of you.`,`The reckoning`,`Kage Sable Nocturne`,[`My clerks called it waste when you burned your file. I agreed with them for about an hour.`,`I kept wondering whether it was worth giving up everything it could tell you.`,`Don't answer. I can see that it was. I had thousands of chances to do the same and never did.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Answer for Nerissa Vale. Her name comes home tonight.`,`The reckoning`,`Kage Sable Nocturne`,[`I found Nerissa Vale's file in my first year. She was nine. She had sold her name for food.`,`I could have returned it. I told myself the file proved how the whole system worked. The truth is I was afraid one return would start the rest.`,`Tell her I read it every winter and still kept it. She should hear that tonight.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Answer for the night name you would not write.`,`The reckoning`,`Kage Sable Nocturne`,[`You refused to write one. That matters more than leaving the space blank.`,`A blank can be filled later. A refusal can't.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Answer for the night name that is yours alone.`,`The reckoning`,`Kage Sable Nocturne`,[`You chose your own name at intake and kept it.`,`I held thousands of names before I understood how simple that was.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Answer for the leaf you tore out of your own file.`,`The reckoning`,`Kage Sable Nocturne`,[`You tore the page from your own file before my clerks could use it.`,`I was angry. I also understood.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`Answer for the night name you wrote to shield someone else.`,`The reckoning`,`Kage Sable Nocturne`,[`You chose a name to protect someone else.`,`The Mirror doesn't understand that. I think you did.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,choices:[{text:`Enough. The Mirror answers now.`,nextPage:25}]},{...i(`The Glass and the Notice`,`The Mirror chamber, the black moon at zenith, Sable's shadow finishing its departure`,`Kage Sable Nocturne`,[`Enough.`,`I still believe opening this tank will destroy people. Look at the market below us. One night has already broken families, and there will be more.`,`The buyer arrives tonight. I won't give it the Mirror, and I won't let you crack the glass because you hope the village can survive it.`,`The Mirror holds everyone, %name. Everyone but you.`,`If you want it opened, go through me.`]),image:`/scenes/story/story-moonshadow-village-100-8.webp`,leftName:`Player`,rightName:`Kage Sable Nocturne`,rightImage:`/portraits/kage-sable-nocturne-hollow.webp`,choices:[{text:`Show her the better truth.`,nextPage:3,requireTrait:`ms88-better-truth-ready`,forbidTrait:`ms88-nyx-proof-deferred`},{text:`Let Nyx say her own name.`,nextPage:9,requireTrait:`ms88-better-truth-deferred`},{text:`Let Iro read the buyer's manifest.`,nextPage:16,requireTrait:`ms92-witness-present`},{text:`Show her the lease breach.`,nextPage:17,requireTrait:`ms85-copied-the-blank-line`},{text:`Show her Nyx's file.`,nextPage:14,requireTrait:`ms88-player-still-holds-nyx-file`,forbidTrait:`ms88-better-truth-ready`},{text:`Show her the return figures.`,nextPage:13,requireTrait:`ms88-return-proven`,forbidTrait:`ms88-better-truth-ready`},{text:`Answer for the shelf. You've been paying its fee for seasons.`,nextPage:18,requireTrait:`ms58-took-the-shelf`},{text:`Answer for my file. I burned it in front of you.`,nextPage:19,requireTrait:`ms70-burned-the-file`},{text:`Answer for Nerissa Vale. Her name comes home tonight.`,nextPage:20,requireTrait:`ms88-nyx-proof-any`},{text:`Answer for the night name you would not write.`,nextPage:21,requireTrait:`ms70-night-name-refused`},{text:`Answer for the night name that is yours alone.`,nextPage:22,requireTrait:`ms70-night-name-claimed`},{text:`Answer for the leaf you tore out of your own file.`,nextPage:23,requireTrait:`ms70-night-name-stolen-back`},{text:`Answer for the night name you wrote to shield someone else.`,nextPage:24,requireTrait:`ms70-night-name-guardian`}]}],[{text:`Open the tank. Every held thing goes home, and the fires are ours to survive.`,conclusion:`The glass opens, and four hundred years of held secrets return to the village by dawn. Confessions, names, and files move back into the hands they came from. Some returns start fights. Some end them. The buyer's payment arrives to find an empty tank. Sable watches the last file leave, lets out one breath, and then attacks as the Gate claims what remains of her.`,trait:`honorable`},{text:`Seal the lethal tenth under a keeper the village may audit: you.`,conclusion:`Nine parts in ten go home. You seal the last tenth, the truths likely to get someone killed, under a covenant the whole market can audit. The keeper is you, and the first public audit is set before the ink dries. Sable reads the terms twice, then signs. The Gate calls in what remains of her before she can put the pen down.`,trait:`merciful`},{text:`Take the Mirror's keeping. The circle needs a holder it can't price.`,conclusion:`You put your hand on the glass and the tank recognizes, for the first time in four centuries, a keeper it cannot appraise: no price, no lien, no prior holder. The lease's enforcement grammar slides off you the way the Hunter slid off a free envelope. The buyer's escrow hangs, unexecutable, over an asset held by an unpriceable thing. Sable laughs once, low and real. 'The circle finally meets a blank line,' she says. 'Hold it, then. And learn what I learned: the tank keeps its keeper too.' The fire in her gives out, and what wears her rises.`,trait:`loyal`}])]};function s(e){return(o[e.storyVillage||e.village]||o[`Stormveil Village`])[e.storyProgress]??null}export{o as n,s as t};